end

"""
 resolve_alpha_sweep(cfg::Config) -> Tuple{Vector{Float64}, Vector{String}}

Resolve the active α-sweep list for Test 16 / Test 34 based on cfg flags.

Priority:
 1. If `ab_custom_alpha_points` is non-empty → use it (labels generated as "α=k").
 2. Else if `ab_use_magic_alphas` is true → use MAGIC_ALPHA_VALUES + MAGIC_ALPHA_LABELS.
 3. Else → single-element list [ab_alpha_test16] with label "default".

The `include_critical` flag guarantees 0.5 is in the sweep set even when
`ab_use_magic_alphas` is true (0.5 is already in MAGIC_ALPHA_POINTS as "1/2").
"""
function resolve_alpha_sweep(cfg::Config)::Tuple{Vector{Float64},Vector{String}}
 if !isempty(cfg.ab_custom_alpha_points)
 vals = copy(cfg.ab_custom_alpha_points)
 labels = [@sprintf("α=%.4f", v) for v in vals]
 # Guarantee 0.5 is in the sweep (critical line) unless explicitly absent
 if !any(v -> abs(v - 0.5) < 1e-9, vals)
 push!(vals, 0.5)
 push!(labels, "1/2 (critical)")
 end
 return vals, labels
 elseif cfg.ab_use_magic_alphas
 return copy(MAGIC_ALPHA_VALUES), copy(MAGIC_ALPHA_LABELS)
 else
 # Single-config sweep at the user-set α
 return [cfg.ab_alpha_test16], [@sprintf("α=%.4f (default)", cfg.ab_alpha_test16)]
 end
end

"""
 generate_extended_magic_alphas(alpha_min, alpha_max) -> Tuple{Vector{Float64},Vector{String}}

Generate a broader α-sweep covering integers, half-integers, π-multiples,
π-fractions π/k, √k, and special constants (φ, e, ln 2, 1/π, ...).
Ported from RH_Unified_v5.jl line 1242. Useful for deep-sweep presets.
"""
function generate_extended_magic_alphas(alpha_min::Real=-16.0, alpha_max::Real=16.0)
 alphas = Float64[]
 labels = String[]
 # Integers
 for a in ceil(Int, alpha_min):floor(Int, alpha_max)
 push!(alphas, Float64(a)); push!(labels, "$a")
 end
 # Half-integers
 for a in ceil(Int, alpha_min - 0.5):floor(Int, alpha_max - 0.5)
 v = a + 0.5
 if alpha_min <= v <= alpha_max
 push!(alphas, v); push!(labels, "$(a)+0.5")
 end
 end
 # π-multiples
 for k in -4:4
 v = k * π
 if alpha_min <= v <= alpha_max
 lbl = k == 0 ? "0" : (k == 1 ? "π" : (k == -1 ? "-π" : "$(k)π"))
 push!(alphas, v); push!(labels, lbl)
 end
 end
 # π-fractions π/k
 for k in [2, 3, 4, 5, 6, 8, 12]
 for sign in [+1, -1]
 v = sign * π / k
 if alpha_min <= v <= alpha_max
 push!(alphas, v); push!(labels, sign > 0 ? "π/$k" : "-π/$k")
 end
 end
 end
 # √k
 for k in [2, 3, 5, 6, 7, 8, 10, 11, 12, 13, 14, 15]
 for sign in [+1, -1]
 v = sign * √k
 if alpha_min <= v <= alpha_max
 push!(alphas, v); push!(labels, sign > 0 ? "√$k" : "-√$k")
 end
 end
 end
 # Special constants
 special = [
 ((1 + √5) / 2, "φ"), (-((1 + √5) / 2), "-φ"),
 (ℯ, "e"), (-ℯ, "-e"), (ℯ / 2, "e/2"), (-ℯ / 2, "-e/2"),
 (1 / ℯ, "1/e"), (-1 / ℯ, "-1/e"),
 (log(2), "ln(2)"), (-log(2), "-ln(2)"),
 (1 / π, "1/π"), (-1 / π, "-1/π"),
 (2π, "2π"), (-2π, "-2π"),
 ]
 for (v, lbl) in special
 if alpha_min <= v <= alpha_max
 push!(alphas, v); push!(labels, lbl)
 end
 end
 # Sort and dedup
 sorted_idx = sortperm(alphas)
 alphas = alphas[sorted_idx]; labels = labels[sorted_idx]
 uniq_v = Float64[]; uniq_l = String[]
 for (a, l) in zip(alphas, labels)
 if isempty(uniq_v) || abs(a - uniq_v[end]) > 1e-10
 push!(uniq_v, a); push!(uniq_l, l)
 end
 end
 return uniq_v, uniq_l
end

 # ── GUE closed-form references ──
# Theoretical pair-correlation, number variance, spectral rigidity, and
# spectral form factor for the Gaussian Unitary Ensemble (GUE).
# These replace inline formulas and the simulated-GUE-matrix reference
# in Tests 13, 14, 30, 36, 37 — giving a cleaner closed-form comparison.
 # # GUE closed-form references

const R_MEAN_GSE = 0.67620 # Gaussian Symplectic Ensemble ⟨r⟩ (Atas et al. 2013)

# Closed-form pair correlation function (Gaudin-Mehta):
# R2_GUE(s) = 1 - (sin(π s) / (π s))^2
# R2_Poisson(s) = 1.0
R2_GUE_theory(s::Real) = s == 0 ? 0.0 : 1.0 - (sin(π * s) / (π * s))^2
R2_Poisson_theory(s::Real) = 1.0

# Spectral form factor (Fourier transform of R2-1):
# K_GUE(t) = t for 0 ≤ t ≤ 1 (ramp)
# K_GUE(t) = 1 for t > 1 (plateau)
# K_GUE(t) = 0 for t < 0
K_GUE_theory(t::Real) = t < 0 ? 0.0 : (t < 1.0 ? Float64(t) : 1.0)

# Number variance (Σ²) GUE asymptotic (Dyson-Mehta):
# Σ²_GUE(L) = (1/π²) · ln(L) + 1/(8π²) for L ≥ 1
# Σ²_Poisson(L) = L
Sigma2_GUE_theory(L::Real) = L <= 0 ? 0.0 : (1/π^2) * log(max(Float64(L), 1.0)) + 1.0/(8π^2)
Sigma2_Poisson_theory(L::Real) = Float64(L)

# Spectral rigidity (Δ₃) GUE asymptotic (Dyson-Mehta):
# Δ₃_GUE(L) = L/15 for L < 1
# Δ₃_GUE(L) = (1/π²) · ln(L) + 0.007 for L ≥ 1
# Δ₃_Poisson(L) = L/15
Delta3_GUE_theory(L::Real) = L <= 0 ? 0.0 :
 Float64(L) < 1 ? Float64(L)/15.0 : (1/π^2) * log(max(Float64(L), 1.0)) + 0.007
Delta3_Poisson_theory(L::Real) = L <= 0 ? 0.0 : Float64(L)/15.0

"""
 classify_universality_class(r) → (class, d_gue, d_goe, d_gse, d_poi)

Returns the nearest RMT universality class to the observed mean spacing ratio ⟨r⟩.
"""
function classify_universality_class(r::Real)
 d_gue = abs(r - R_MEAN_GUE)
 d_goe = abs(r - R_MEAN_GOE)
 d_gse = abs(r - R_MEAN_GSE)
 d_poi = abs(r - R_MEAN_POISSON)
 d_min = min(d_gue, d_goe, d_gse, d_poi)
 class = d_min == d_gue ? "GUE" : d_min == d_goe ? "GOE" : d_min == d_gse ? "GSE" : "Poisson"
 return (class, d_gue, d_goe, d_gse, d_poi)
end

"""
 compute_R2_KDE(eigs, s_values; bw=0.15, unfold_window=0.05)

Gaussian KDE estimator for the pair correlation function R₂(s).
Uses local-mean unfolding with sliding window of relative size `unfold_window`.
Bandwidth bw = 0.15 (Gaussian kernel). Cap to first 4000 points for speed.

Returns a Vector{Float64} of R₂(s) values for each s in s_values.
"""
function compute_R2_KDE(eigs::AbstractVector{<:Real},
 s_values::AbstractVector{<:Real};
 bw::Float64=0.15,
 unfold_window::Float64=0.05)
 n = length(eigs)
 n < 10 && return zeros(Float64, length(s_values))
 s = sort(Float64.(eigs))
 n_pts = length(s)
 window = max(3, round(Int, n_pts * unfold_window))
 unfolded = zeros(Float64, n_pts)
 unfolded[1] = 0.0
 for i in 2:n_pts
 i_lo = max(1, i - window)
 i_hi = min(n_pts, i + window)
 local_eigs = s[i_lo:i_hi]
 local_density = length(local_eigs) / (local_eigs[end] - local_eigs[1] + 1e-12)
 unfolded[i] = unfolded[i-1] + (s[i] - s[i-1]) * local_density
 end
 mean_spacing = (unfolded[end] - unfolded[1]) / (n_pts - 1)
 if mean_spacing > 1e-12
 unfolded ./= mean_spacing
 end
 # Cap to first M points for speed (R₂ is local statistic, M=4000 enough)
 M = min(n_pts, 4000)
 pair_distances = Float64[]
 sizehint!(pair_distances, M * (M - 1) ÷ 2)
 @inbounds for i in 1:M, j in (i+1):M
 push!(pair_distances, unfolded[j] - unfolded[i])
 end
 R2 = zeros(Float64, length(s_values))
 norm_factor = 1.0 / (M * bw * sqrt(2π))
 @inbounds for (idx, sv) in enumerate(s_values)
 if sv <= 0
 R2[idx] = 0.0
 continue
 end
 weights = exp.(-((pair_distances .- sv) .^ 2) / (2 * bw^2))
 R2[idx] = sum(weights) * norm_factor
 end
 return R2
end

"""
 compute_K_form_factor(eigs, t_values; smooth_window=3, preserve_ramp=true,
 ramp_threshold=0.5, eigs_per_seed=0)

Connected spectral form factor K(t) = (1/N)|Σ exp(2πi t x_i)|² - 1.
Clamped at 0 (negative values are noise). If eigs_per_seed > 0 and the spectrum
contains multiple seeds, K(t) is computed per-seed and averaged (removes
inter-seed boundary artifacts).
"""
function compute_K_form_factor(eigs::AbstractVector{<:Real},
 t_values::AbstractVector{<:Real};
 smooth_window::Int=3,
 preserve_ramp::Bool=true,
 ramp_threshold::Float64=0.5,
 eigs_per_seed::Int=0)
 n = length(eigs)
 n < 10 && return zeros(Float64, length(t_values))
 if eigs_per_seed > 0 && n > eigs_per_seed
 n_seeds_actual = n ÷ eigs_per_seed
 K_sum = zeros(Float64, length(t_values))
 K_count = 0
 for s in 0:(n_seeds_actual - 1)
 i_start = s * eigs_per_seed + 1
 i_end = min((s + 1) * eigs_per_seed, n)
 if i_end - i_start < 10
 continue
 end
 K_seed = _compute_K_single_seed(eigs[i_start:i_end], t_values;
 smooth_window=smooth_window,
 preserve_ramp=preserve_ramp,
 ramp_threshold=ramp_threshold)
 K_sum .+= K_seed
 K_count += 1
 end
 if K_count > 0
 return K_sum ./ K_count
 end
 end
 return _compute_K_single_seed(eigs, t_values;
 smooth_window=smooth_window,
 preserve_ramp=preserve_ramp,
 ramp_threshold=ramp_threshold)
end

function _compute_K_single_seed(eigs::AbstractVector{<:Real},
 t_values::AbstractVector{<:Real};
 smooth_window::Int=3,
 preserve_ramp::Bool=true,
 ramp_threshold::Float64=0.5)
 n = length(eigs)
 n < 10 && return zeros(Float64, length(t_values))
 s = sort(Float64.(eigs))
 n_pts = length(s)
 window = max(3, round(Int, n_pts * 0.05))
 unfolded = zeros(Float64, n_pts)
 unfolded[1] = 0.0
 @inbounds for i in 2:n_pts
 i_lo = max(1, i - window)
 i_hi = min(n_pts, i + window)
 local_eigs = s[i_lo:i_hi]
 local_density = length(local_eigs) / (local_eigs[end] - local_eigs[1] + 1e-12)
 unfolded[i] = unfolded[i-1] + (s[i] - s[i-1]) * local_density
 end
 mean_spacing = (unfolded[end] - unfolded[1]) / (n_pts - 1)
 if mean_spacing > 1e-12
 unfolded ./= mean_spacing
 end
 K = zeros(Float64, length(t_values))
 @inbounds for (idx, t) in enumerate(t_values)
 if t == 0.0
 K[idx] = 0.0
 continue
 end
 phase = 2π * t * unfolded
 ph = exp.(im .* phase)
 # NO "-1" here. For ABSOLUTE unfolded positions (mean spacing
 # 1, spanning [0, n]) the analytic GUE form factor is K(τ) = 1 − tri(τ)
 # (tri = triangle on [0,1]) — i.e. the ramp K=τ for τ≤1 and the plateau
 # K=1 for τ≥1 arise from (1/n)|Σ|² DIRECTLY. Subtracting 1 (the
 # self-pair count for CENTERED positions) clipped the whole ramp to 0
 # (measured: K ≈ 0 at every t, RMS vs min(t,1) = 0.63).
 K[idx] = max(0.0, abs2(sum(ph)) / n)
 end
 if length(K) > 2 * smooth_window
 K_smoothed = copy(K)
 @inbounds for i in (smooth_window+1):(length(K) - smooth_window)
 if preserve_ramp && t_values[i] < ramp_threshold
 continue
 end
 K_smoothed[i] = mean(K[(i - smooth_window):(i + smooth_window)])
 end
 K = K_smoothed
 end
 return K
end

"""
 compute_byte_level_diagnostics(eigs_ab, r_ab; n_bytes=200_000, seed=12345, byte_tol=0.02)

Two independent robustness checks:
 (a) BYTE-QUANTIZATION: quantize eigvals to 256 levels, recompute ⟨r⟩. If ⟨r⟩
 survives (|Δr| < byte_tol), the GUE classification is not a float-precision artifact.
 (b) RNG ENTROPY: sample n_bytes from MersenneTwister, compute Shannon entropy
 (ideal = 8.0 bits) and χ²_z (CLT-approx, |z|<3.0 → uniform).

Returns NamedTuple with all diagnostics + byte_match Bool.
"""
function compute_byte_level_diagnostics(eigs_ab::AbstractVector{<:Real}, r_ab::Real;
 n_bytes::Int=200_000, seed::Int=12345,
 byte_tol::Float64=0.02)
 # (a) Quantize eigvals to 256 levels and recompute ⟨r⟩
 lo, hi = minimum(eigs_ab), maximum(eigs_ab)
 span = hi - lo
 r_quantized = NaN
 byte_quant_diff = NaN
 if span > 0
 levels = clamp.(round.(Int, (eigs_ab .- lo) ./ span .* 255), 0, 255)
 quantized = lo .+ (levels ./ 255) .* span
 if length(quantized) >= 3
 sr_q = Float64[]
 sorted_q = sort(quantized)
 for i in 1:(length(sorted_q) - 2)
 a = sorted_q[i+1] - sorted_q[i]
 b = sorted_q[i+2] - sorted_q[i+1]
 if b > 0
 push!(sr_q, min(a, b) / max(a, b))
 end
 end
 if !isempty(sr_q)
 r_quantized = mean(sr_q)
 byte_quant_diff = abs(r_quantized - r_ab)
 end
 end
 end
 byte_quant_robust = !isnan(byte_quant_diff) && byte_quant_diff < byte_tol

 # (b) RNG byte entropy / uniformity
 rng_local = MersenneTwister(seed)
 bytes_arr = rand(rng_local, UInt8, n_bytes)
 counts = zeros(Int, 256)
 @inbounds for b in bytes_arr
 counts[Int(b) + 1] += 1
 end
 probs = counts ./ n_bytes
 shannon_entropy = -sum(p > 0 ? p * log2(p) : 0.0 for p in probs)
 expected = n_bytes / 256
 chi2_stat = sum((counts .- expected) .^ 2 ./ expected)
 df = 255
 chi2_z = (chi2_stat - df) / sqrt(2.0 * df)
 rng_uniform_ok = abs(chi2_z) < 3.0
 entropy_ok = shannon_entropy > 7.9
 byte_match = byte_quant_robust && rng_uniform_ok && entropy_ok

 return (r_byte_quantized=r_quantized, byte_quant_diff=byte_quant_diff,
 byte_quant_robust=byte_quant_robust, rng_entropy_bits=shannon_entropy,
 rng_chi2_z=chi2_z, rng_uniform_ok=rng_uniform_ok, byte_match=byte_match)
end

"""
byte_quantize_r(eigs) -> Float64

⟨r⟩ of a spectrum after 256-level (byte) quantization — the quantization
half of `compute_byte_level_diagnostics`, factored out so Test 36 can apply
it to MANY local windows (multi-window robustness average) without redoing
the expensive RNG-entropy part each time. NaN when the window is degenerate
(span 0 or fewer than 3 usable levels).
"""
function byte_quantize_r(eigs::AbstractVector{<:Real})::Float64
 lo, hi = minimum(eigs), maximum(eigs)
 span = hi - lo
 span > 0 || return NaN
 levels = clamp.(round.(Int, (eigs .- lo) ./ span .* 255), 0, 255)
 quantized = sort(lo .+ (levels ./ 255) .* span)
 sr = Float64[]
 for i in 1:(length(quantized) - 2)
 a = quantized[i+1] - quantized[i]
 b = quantized[i+2] - quantized[i+1]
 if b > 0
 push!(sr, min(a, b) / max(a, b))
 end
 end
 return isempty(sr) ? NaN : mean(sr)
end

"""
 connes_self_duality_defect(α, Nx, Ny) → Float64

a finite open lattice satisfies an APPROXIMATE spectral duality under
α ↔ 1/α (which equals α ↔ 2 at α=1/2). The duality is exact on the INFINITE
lattice / Bloch bands; on a finite lattice it is spoiled by boundary effects.

This function builds H(α) and H(1/α) on an OPEN lattice and returns the
relative L² distance between their sorted eigenvalue spectra:

 Δ = || eigvals(H(α)) − eigvals(H(1/α)) ||_2 / || eigvals(H(α)) ||_2

At α = 1/2: Δ is small (boundary-spoiled self-duality).
Off-critical: Δ is larger.
"""
function connes_self_duality_defect(α::Float64, Nx::Int, Ny::Int)
 # Use OPEN boundary conditions to avoid the α·Ny ∈ ℤ constraint
 # (the self-duality is a property of the bulk spectrum, not the BC).
 cfg_α = ABCloudConfig(Nx, Ny, Vortex[], α, 1.0, :open, 4.0)
 cfg_1α = ABCloudConfig(Nx, Ny, Vortex[], 1.0/α, 1.0, :open, 4.0)
 H_α = build_ab_cloud_hamiltonian(cfg_α)
 H_1α = build_ab_cloud_hamiltonian(cfg_1α)
 # Values-only Hermitian path (user size-standard 2026-08-30): the old
 # safe_eigvals ran FULL zgeev WITH eigenvectors — at 72² that is minutes
 # and multiple GB, which priced the 72/96 standard out of Tests 17/17b.
 # The builder guarantees H_ij = conj(H_ji) (Hermitian), so heevr
 # values-only returns the same real spectrum at ~50× lower cost.
 ev_α = sort(eigvals(Hermitian(H_α)))
 ev_1α = sort(eigvals(Hermitian(H_1α)))
 return norm(ev_α - ev_1α) / max(norm(ev_α), 1e-30)
end

"""
 spectral_symmetry_defect(α, Nx, Ny) → Float64

Measure the E → -E spectral symmetry of H(α) on a torus.

For α = 1/2 (Connes self-dual point), the Harper model has chiral symmetry
class AIII: the spectrum is symmetric under E → -E. The defect is

 Δ = || sort(eigvals) + reverse(sort(eigvals)) || / || sort(eigvals) ||

which vanishes iff for every +E there is a matching -E.
"""
function spectral_symmetry_defect(α::Float64, Nx::Int, Ny::Int)
 # W=0.0 — these helpers are documented for the CLEAN lattice
 # ("At α = 1/2 … should return 4"). The hardcoded W=4.0 added the
 # builder's residual ε noise to the diagonal and destroyed the exact
 # zero modes (count 0 instead of 4) — Test 17 could never PASS.
 cfg = ABCloudConfig(Nx, Ny, Vortex[], α, 1.0, :torus, 0.0)
 H = build_ab_cloud_hamiltonian(cfg)
 ev = sort(eigvals(Hermitian(H))) # values only (RAM: no eigenvector block)
 # For spectral symmetry E → -E: ev[i] + ev[N+1-i] = 0 for all i
 # So ev + reverse(ev) = 0 vector. Normalise by ||ev||.
 return norm(ev + reverse(ev)) / max(norm(ev), 1e-30)
end

"""
 count_zero_eigenvalues(α, Nx, Ny; tol=1e-8) → Int

Count the number of eigenvalues of H(α) on a torus that are within `tol` of 0.
At α = 1/2 with even Nx, Ny: should return 4 (the 4 Dirac-cone zero modes
from the (π,π) Dirac points in the magnetic BZ).
At α = 1/3 (q=3): should return 0 (gapped spectrum).
"""
function count_zero_eigenvalues(α::Float64, Nx::Int, Ny::Int; tol::Float64=1e-8)
 # W=0.0 — these helpers are documented for the CLEAN lattice
 # ("At α = 1/2 … should return 4"). The hardcoded W=4.0 added the
 # builder's residual ε noise to the diagonal and destroyed the exact
 # zero modes (count 0 instead of 4) — Test 17 could never PASS.
 cfg = ABCloudConfig(Nx, Ny, Vortex[], α, 1.0, :torus, 0.0)
 H = build_ab_cloud_hamiltonian(cfg)
 # Values-only Hermitian path (see connes_self_duality_defect note):
 # safe_eigvals (full zgeev + vectors) made count_zero the runtime
 # bottleneck at the 72×72 launch-standard lattice.
 ev = sort(eigvals(Hermitian(H)))
 return count(e -> abs(e) < tol, ev)
end

"""
 dirac_cone_velocity(eigs; centre=0.0, window=0.3) → (v_F, found, info)

Locate a Dirac cone in the spectrum: a point where two bands touch linearly
at E ≈ 0. We approximate v_F by examining the density of states near E = 0:

 v_F ≈ (1/2) · (E_{k+1} − E_{k-1}) / Δk

where Δk is the lattice momentum step and k is the index of the eigenvalue
closest to zero. For an L×L lattice with periodic BC, Δk = 2π/L, and the
linear dispersion E(k) ≈ v_F · |k| implies

 v_F ≈ L/(4π) · (E_{k+1} − E_{k-1})

Returns `(v_F, found, info_string)`. v_F is set to NaN if no eigenvalue is
within `window` of `centre` (no Dirac cone detected).
"""
function dirac_cone_velocity(eigs::Vector{<:Real}; centre::Float64=0.0,
 window::Float64=0.3, L::Int=0)
 L == 0 && (L = round(Int, sqrt(length(eigs))))
 sorted_eigs = sort(eigs)
 n = length(sorted_eigs)
 # For a 2D Dirac cone with dispersion E(k) = v_F·|k|,
 # the smallest POSITIVE eigenvalue on an L×L torus (smallest nonzero |k|)
 # is E_min = v_F · 2π/L. Hence v_F = E_min · L / (2π).
 # We find the smallest positive eigenvalue > tol (skipping zero modes
 # which arise from the 4-fold Dirac-point degeneracy at α=1/2).
 tol = 1e-6
 pos_eigs = filter(e -> e > tol, sorted_eigs)
 neg_eigs = filter(e -> e < -tol, sorted_eigs)
 zero_count = count(e -> abs(e) <= tol, sorted_eigs)
 if isempty(pos_eigs) || isempty(neg_eigs)
 return (NaN, false, "no Dirac cone: spectrum is gapped or one-sided")
 end
 E_min = minimum(pos_eigs)
 # The smallest k vector on an L×L torus is 2π/L (single Dirac cone at Γ)
 # or 2π·sqrt(2)/L (Dirac cone at (π/L, π/L)). For α=1/2 Harper, the
 # Dirac cones sit at (π, π) in the magnetic BZ, so the smallest |k| from
 # the cone is 2π/L. Hence:
 v_F = E_min * L / (2π)
 info = "v_F ≈ $(round(v_F, digits=4)) (E_min=$(round(E_min,digits=4)), L=$L, zero_modes=$zero_count)"
 found = abs(E_min) < window
 return (v_F, found, info)
end

# RETIRED (v19.1 audit): tknn_chern_number_first_band — the old twisted-torus
# single-state FHS helper. It was never called by any test (superseded by
# harper_chern_first_band below), its docstring was corrupted mid-sentence,
# and its plaquette holonomy mixed non-inverted links (Ux·Uy·Ux_inv·Uy_inv
# with Uy_inv NOT the inverse of Uy) — kept out of the codebase; the pitfall
# is documented in the harper_chern_first_band docstring instead.

"""
 harper_chern_first_band(alpha; n_kx=24, n_ky=8, mass=0.0)
 → (C1::Int, min_gap::Float64, n_singular_links::Int)

TEXTBOOK TKNN Chern number of the lowest Hofstadter sub-band: Fukui–
Hatsugai–Suzuki lattice field strength on the MAGNETIC Brillouin zone,
computed on the q×q Harper cell (q = denominator of alpha = p/q).

WHY NOT THE TWISTED-TORUS FHS (the retired test22 path): on a finite L×L
torus the twisted-BC family H(φx, φy) shifts the crystal momentum
k → k + (φx/L, φy/L); at commensurate flux the occupied band's k-set is
mapped onto ITSELF (a permutation), so the twist-space occupied bundle is
topologically TRIVIAL (validated replica: Berry curvature nonzero on every
plaquette yet ΣF = 0.0000 exactly) and the single-eigenvector links
additionally walk into band degeneracies → the old "C₁" was a degeneracy
lottery (+2/−5/−6/+4 across grids/LAPACKs, not reproducible).

Construction (gauge matched to build_ab_cloud_hamiltonian, phase 2πα·iy on
right bonds → magnetic cell = q sites along y):
    H[m,m]   = −2t·cos(kx + 2πα·m)              (m = 0..q−1)
    H[m,m+1] = −t;  H[q−1,0] = −t·e^{+i·q·ky}   (+ h.c.)
k-grid: kx = 2π·a/n_kx, ky = (2π/q)·b/n_ky — the MAGNETIC BZ (ky period
2π/q; sampling the full ky period folds q sub-bands into "band 1" and
returns q·C₁ — replica measured +3/+4/+5 at α=1/3,1/4,1/5).

Validation (scripts/validate_harper2.py, numpy mirror):
 • Harper bands == site-space torus spectrum to 6.2e-15 (construction exact)
 • C₁ = +1 at α = 1/3, 1/4, 1/5 (literature anchors, TKNN Diophantine t₁=+1)
 • size ladder L = 9..72 (n_k = L×L/q) stable +1 — cost-free (q×q solves)
At α = 1/2 (q=2) the two sub-bands TOUCH at Dirac points (min gap ≈ 1e-16
on any grid): the per-band C₁ is undefined (links may be singular — counted
in n_singular_links). `mass ≠ 0` adds mass·diag((−1)^m), opening the gap;
the regularized branch yields C₁ = 0 for BOTH mass signs (chirality-balanced
Dirac points; ladder-stable) — see scripts/validate_chern_fhs.py.
"""
function harper_chern_first_band(alpha::Float64; n_kx::Int=24, n_ky::Int=8,
                                 mass::Float64=0.0)
 rat = rationalize(alpha; tol=1e-10)
 p, q = numerator(rat), denominator(rat)
 (q < 2 || q > 64) && error("harper_chern_first_band: alpha must be rational p/q with 2 ≤ q ≤ 64, got $alpha")
 bands = Array{Vector{ComplexF64},2}(undef, n_kx, n_ky)
 min_gap = Inf
 for a in 1:n_kx, b in 1:n_ky
  kx = 2π * (a - 1) / n_kx
  ky = (2π / q) * (b - 1) / n_ky
  Hq = zeros(ComplexF64, q, q)
  for m in 0:(q - 1)
   Hq[m+1, m+1] += -2.0 * cos(kx + 2π * alpha * m)
   if m + 1 ≤ q - 1
    Hq[m+1, m+2] += -1.0
    Hq[m+2, m+1] += -1.0
   end
  end
  Hq[q, 1] += -exp(im * q * ky)
  Hq[1, q] += -exp(-im * q * ky)
  if mass != 0.0
   for m in 0:(q - 1)
    Hq[m+1, m+1] += mass * (m % 2 == 0 ? 1.0 : -1.0)
   end
  end
  E = eigen(Hermitian(Hq))
  bands[a, b] = E.vectors[:, 1]
  min_gap = min(min_gap, E.values[2] - E.values[1])
 end
 n_sing = 0
 _link(u, v) = begin
  z = dot(u, v)
  if abs(z) < 1e-14
   n_sing += 1
   return ComplexF64(1.0, 0.0) # degenerate link — counted, excluded from winding
  end
  z / abs(z)
 end
 C = 0.0
 for a in 1:n_kx, b in 1:n_ky
  a1, b1 = mod1(a + 1, n_kx), mod1(b + 1, n_ky)
  u1 = _link(bands[a, b], bands[a1, b])
  u2 = _link(bands[a1, b], bands[a1, b1])
  u3 = _link(bands[a, b1], bands[a1, b1])
  u4 = _link(bands[a, b], bands[a, b1])
  C += angle(u1 * u2 * conj(u3) * conj(u4))
 end
 return round(Int, C / (2π)), min_gap, n_sing
end

# RETIRED (v19.1 audit): ab_cloud_twisted_hamiltonian — the twisted-BC family
# H(φx, φy). It had NO remaining callers (the only consumer, the twisted-torus
# FHS path, is itself retired — see the harper_chern_first_band docstring):
# at commensurate flux the twist is a crystal-momentum shift k → k + (φ/L),
# the occupied k-set maps onto itself, and the twist-space bundle is
# topologically trivial — a degeneracy lottery, not a Chern number.

"""
 random_vortex_configuration(Nv, Nx, Ny; q_magnitude=1.0,
 enforce_neutrality=true, rng=default_rng(),
 place_at_centers=false) → Vector{Vortex}

Generate a random vortex configuration with `Nv` vortices on the `Nx`×`Ny`
lattice.

`q_magnitude::Float64=1.0` — magnitude of each vortex charge. The
actual charges are ±`q_magnitude`. Default 1.0 (integer) gives ZERO spectral
effect by the Byers-Yang theorem; the user should pass a fractional value
(e.g. 0.3) for a real AB effect.

`place_at_centers::Bool=false` — if true, place vortices at random
PLAQUETTE CENTERS (half-integer positions (ix+0.5, iy+0.5)). This is the
cleanest configuration for the Dirac string implementation: the string
extends from the center of a plaquette to the right edge, crossing exactly
one column of vertical bonds per row.

The configuration is "net neutral" by default (sum q_k = 0 when Nv is even),
"""
function random_vortex_configuration(Nv::Int, Nx::Int, Ny::Int;
 q_magnitude::Float64=1.0,
 enforce_neutrality::Bool=true,
 rng=default_rng(),
 place_at_centers::Bool=false)
 vortices = Vector{Vortex}(undef, Nv)
 for k in 1:Nv
 if place_at_centers
 # Place at center of a random plaquette (ix+0.5, iy+0.5)
 # Avoid the boundary plaquettes to keep the Dirac string well-defined.
 # OFF-BY-ONE FIX: the old `1 + rand(1:Nx-1)` sampled ix ∈ 2..Nx →
 # x ∈ 2.5..Nx+0.5, i.e. the LAST "plaquette" stuck out past the right
 # edge (x = Nx+0.5 is the boundary, not a plaquette center) and the
 # leftmost plaquette (x = 1.5) could never be drawn. Plaquette centers
 # of an Nx-column lattice are ix+0.5 for ix ∈ 1..Nx-1.
 ix = rand(rng, 1:Nx-1)
 iy = rand(rng, 1:Ny-1)
 x = Float64(ix) + 0.5
 y = Float64(iy) + 0.5
 else
 x = Nx * (0.5 + 0.4 * (rand(rng) - 0.5)) # avoid lattice edges
 y = Ny * (0.5 + 0.4 * (rand(rng) - 0.5))
 end
 # Odd-Nv charge assignment. With enforce_neutrality=true and
 # an EVEN Nv the split is exactly Nv/2 vs Nv/2 (net charge 0). The old code
 # fell through to a RANDOM ±q draw when Nv is odd — the net charge then
 # performed a random walk of size ±√Nv across realizations (e.g. preset_full
 # uses Nv=25: net charge varied 0,±2,±4,… run to run, silently changing the
 # vortex potential between realizations). True neutrality is impossible for
 # odd Nv with equal |q|, so we now use the DETERMINISTIC minimal-imbalance
 # split ⌈Nv/2⌉ vs ⌊Nv/2⌋ (|net| = 1, fixed) — reproducible and unbiased.
 q = if enforce_neutrality && iseven(Nv)
 k ≤ Nv ÷ 2 ? q_magnitude : -q_magnitude
 elseif enforce_neutrality && isodd(Nv)
 k ≤ (Nv + 1) ÷ 2 ? q_magnitude : -q_magnitude # 13 vs 12, |net|=1
 else
 rand(rng, [-q_magnitude, +q_magnitude])
 end
 vortices[k] = Vortex(x, y, q)
 end
 return vortices
end


# ─────────────────────────────────────────────────────────────────────────────
 # 6c. 3D PSL(2,7) KLEIN QUARTIC EMBEDDING
# ─────────────────────────────────────────────────────────────────────────────

# The v23 monograph (§2.4, §6.3) repeatedly invokes PSL(2,7) (the automorphism
# group of the Klein quartic, order 168) as the "topological hardware" on which
 # the AB-cloud software runs. Earlier editions, however, never implemented an explicit
# 3D realisation of PSL(2,7). This section provides one.

# MATHEMATICAL BACKGROUND
# -----------------------
# The Klein quartic K₄ is the genus-3 Riemann surface defined by the projective
# curve

# x⁴ + y⁴ + z⁴ = 0 ⊂ CP²

# It is the unique Hurwitz surface of genus 3, with automorphism group
# |Aut(K₄)| = 168 = 84·(g−1) — the maximum possible for a genus-3 surface by
# the Hurwitz bound. Aut(K₄) ≅ PSL(2,7) ≅ GL(3,2) ≅ L₃(2).

# 3D EMBEDDING DECISION: K₄ in S³ via the (3,4)-torus-knot Seifert surface
# -----------------------------------------------------------------------
# We embed K₄ in the 3-sphere S³ = { (z₁, z₂) ∈ C² : |z₁|² + |z₂|² = 1 } via
# the Milnor fibre of the Brieskorn–Pham singularity

# z₁³ + z₂⁴ = 0

# The link of this singularity is the (3,4)-torus knot, and its Milnor fibre
# is a genus-3 Seifert surface with automorphism group of order 168 — the
# Klein quartic. (Cf. Milnor 1968, Brieskorn 1966.)

# Why this embedding (and not, say, T³)?
# - S³ has no boundary and is simply connected → cleanest ambient space
# - The (3,4)-torus knot lives naturally in S³ (as the intersection of
# |z₁|²+|z₂|²=1 with z₁³+z₂⁴=0)
# - The Seifert surface genus g = (p−1)(q−1)/2 = (3−1)(4−1)/2 = 3 ✓
# - The (3,4) knot's symmetry group (dihedral of order 14 from the knot, plus
# the super-group of the Brieskorn sphere Σ(2,3,7)) contains PSL(2,7) as the
# orientation-preserving subgroup of the (2,3,7) triangle group.

# Alternative considered: T³ (3-torus). Rejected because:
# - The torus group is abelian (Z³) and cannot host the non-abelian PSL(2,7)
# as a subgroup of its diffeomorphism group in a non-trivial way
# - The natural periodic boundary conditions of T³ would break the genus-3
# topology of K₄
# - S³ is the universal cover of SO(3) (rotations of R³), which makes the
# 3D rotation representation of PSL(2,7) natural

# EXPLICIT PSL(2,7) GENERATORS IN SO(3)
# --------------------------------------
# PSL(2,7) has presentation ⟨ S, T | S² = T³ = (ST)⁷ = 1 ⟩ (the (2,3,7) triangle
# group quotiented by its commutator subgroup, which gives the Hurwitz group
# of order 168). We realise:

# S = rotation by π about the x-axis (order 2)
# T = rotation by 2π/3 about the z-axis (order 3)
# ST is a rotation by 2π/7 about a carefully chosen axis

# These three rotations, composed, generate all 168 elements of PSL(2,7) as
# 3×3 real orthogonal matrices of determinant +1.

"""
 rotation_matrix(axis, angle) → Matrix{Float64}

Rodrigues' rotation formula: returns the 3×3 rotation matrix for a rotation
by `angle` (radians) about the unit vector `axis` (3-vector).
"""
function rotation_matrix(axis::AbstractVector{<:Real}, angle::Real)
 n = norm(axis)
 n < 1e-15 && return Matrix{Float64}(I, 3, 3)
 x, y, z = Float64.(axis) / n
 c = cos(angle)
 s = sin(angle)
 C = 1.0 - c
 return [
 c+x*x*C x*y*C-z*s x*z*C+y*s;
 y*x*C+z*s c+y*y*C y*z*C-x*s;
 z*x*C-y*s z*y*C+x*s c+z*z*C
 ]
end

"""
 psl27_generators_so3() → (S, T, ST_axis)

Returns the two generators of PSL(2,7) as 3×3 special orthogonal matrices:
- `S`: rotation by π about the x-axis (order 2)
- `T`: rotation by 2π/3 about the z-axis (order 3)
- `ST_axis`: the axis about which S·T is a rotation by 2π/7 (order 7)

The choice of ST_axis is critical: ST must be order 7. The standard
(2,3,7) triangle group realisation places this axis along
(1, 1, 1)/√3 — but only when S and T are chosen with the correct relative
orientation. We verify the order-7 condition explicitly in
`verify_psl27_generators()`.
"""
function psl27_generators_so3()
 # S = rotation by π about x-axis
 S = rotation_matrix([1.0, 0.0, 0.0], π)
 # T = rotation by 2π/3 about z-axis
 T = rotation_matrix([0.0, 0.0, 1.0], 2π / 3)
 # ST axis — we use (cos(π/7), sin(π/7), 0) rotated into a generic position
 # that makes ST order 7. The axis is determined by the S, T choice.
 # We'll compute it after constructing S and T.
 ST = S * T
 # Extract the axis of ST from its real eigenvector (eigenvalue 1)
 F = eigen(ST)
 # find the eigenvalue closest to 1
 idx = argmin(abs.(F.values .- 1.0))
 ST_axis = real.(F.vectors[:, idx])
 ST_axis = ST_axis / norm(ST_axis)
 return S, T, ST_axis
end

"""
 verify_psl27_generators(S, T) → (ok, info)

Verify that the (S, T) pair satisfies the (2,3,7) triangle group relations:
- S² = I
- T³ = I
- (S·T)⁷ = I
- (S·T⁻¹)⁴ ≠ I (so it's not the smaller (2,3,4) octahedral group)

Returns `(ok, info_string)`.
"""
function verify_psl27_generators(S::Matrix{Float64}, T::Matrix{Float64})
 I3 = Matrix{Float64}(I, 3, 3)
 err_S2 = norm(S^2 - I3)
 err_T3 = norm(T^3 - I3)
 ST7 = (S * T)^7
 err_ST7 = norm(ST7 - I3)
 STinv4 = (S * inv(T))^4
 err_STinv4 = norm(STinv4 - I3)
 ok = err_S2 < 1e-10 && err_T3 < 1e-10 && err_ST7 < 1e-10 && err_STinv4 > 1e-3
 info = "‖S²−I‖=$(round(err_S2,sigfig=3)), ‖T³−I‖=$(round(err_T3,sigfig=3)), " *
 "‖(ST)⁷−I‖=$(round(err_ST7,sigfig=3)), ‖(ST⁻¹)⁴−I‖=$(round(err_STinv4,sigfig=3))"
 return ok, info
end

"""
 psl27_full_group(S, T; max_order=200) → Vector{Matrix{Float64}}

Generate the full PSL(2,7) group of order 168 by closing under S and T
multiplication. Stops when no new elements are found or `max_order` reached.

Returns a vector of distinct 3×3 matrices. The expected length is 168.
"""
function psl27_full_group(S::Matrix{Float64}, T::Matrix{Float64}; max_order::Int=200)
 n = size(S, 1)
 I_n = Matrix{Float64}(I, n, n)
 elements = [I_n]
 seen = Set{UInt64}()
 push!(seen, hash(round.(I_n, digits=10)))
 queue = [I_n]
 while !isempty(queue) && length(elements) < max_order
 g = popfirst!(queue)
 for h in [S, T]
 new_g = g * h
 key = hash(round.(new_g, digits=10))
 if !(key in seen)
 push!(seen, key)
 push!(elements, new_g)
 push!(queue, new_g)
 end
 end
 end
 return elements
end

"""
 fano_plane_points() → Vector{Vector{Int}}

The Fano plane is the projective plane PG(2,2) over GF(2): 7 points, 7 lines,
3 points per line, 3 lines through each point. Its automorphism group is
PSL(2,7) of order 168 (the same group that acts on the Klein quartic).

We label the points 1..7 and return the 7 lines as triples of point indices.
This is the standard "schoolgirl" representation.
"""
function fano_plane_points()
 # 7 lines of the Fano plane (each line is a triple of point indices 1..7)
 # Standard labelling: points = {1,2,3,4,5,6,7}
 # Lines: {1,2,3}, {1,4,5}, {1,6,7}, {2,4,6}, {2,5,7}, {3,4,7}, {3,5,6}
 return [
 [1, 2, 3], [1, 4, 5], [1, 6, 7],
 [2, 4, 6], [2, 5, 7], [3, 4, 7], [3, 5, 6]
 ]
end

"""
 fano_plane_to_R3() → Vector{Vector{Float64}}

Embed the 7 Fano-plane points as 7 vertices in R³ respecting the 168-element
PSL(2,7) symmetry. We place them on the unit sphere at the vertices of an
octahedron-plus-centre configuration that is invariant under the (2,3,7)
triangle group action.

Returns 7 vertex positions (unit vectors in R³).

NOTE: A perfectly symmetric realisation of PSL(2,7) acting on R³ is impossible
because the smallest faithful real representation of PSL(2,7) is 6-dimensional
(the irreducible 3D complex rep). We therefore use a PROJECTIVE/AFFINE
realisation: PSL(2,7) acts as signed permutations of the 7 Fano-plane points,
preserving the 7 lines. This is the faithful permutation representation of
degree 7 (the natural PSL(2,7) → S₇ embedding, factor 168/7! = small but
faithful since 7! / 168 = 30 ≠ 0).
"""
function fano_plane_to_R3()
 # Place 7 points: 1 at origin, 6 at ±x, ±y, ±z (octahedron)
 # PSL(2,7) acts as the orientation-preserving signed permutations that
 # preserve the Fano-plane incidence structure.
 return [
 [0.0, 0.0, 0.0], # point 1 (origin)
 [1.0, 0.0, 0.0], # point 2
 [-1.0, 0.0, 0.0], # point 3
 [0.0, 1.0, 0.0], # point 4
 [0.0, -1.0, 0.0], # point 5
 [0.0, 0.0, 1.0], # point 6
 [0.0, 0.0, -1.0], # point 7
 ]
end

"""
 embed_klein_quartic_in_S3(; n_samples=168) → KleinQuartic3D

Embed the Klein quartic K₄ in S³ via the Milnor fibre of z₁³ + z₂⁴ = 0.

The Milnor fibre is the surface { (z₁, z₂) ∈ C² : z₁³ + z₂⁴ = ε } ∩ S³,
which for small ε > 0 is a smooth genus-3 surface. For ε = 0 we get the cone
on the (3,4)-torus knot, but for ε ≠ 0 we get the smooth Seifert surface.

Sampling strategy:
1. Parametrise S³ ⊂ C² via (z₁, z₂) = (cos θ · e^{iφ₁}, sin θ · e^{iφ₂}).
2. For each (θ, φ₁), solve z₁³ + z₂⁴ = ε for z₂ (4 branches) — this gives
 a 2-real-dimensional surface in S³.
3. Sample θ ∈ [0, π/2], φ₁ ∈ [0, 2π), and compute the 4 corresponding (φ₂)
 values per (θ, φ₁) → 4 · n_θ · n_φ vertices.

Returns a `KleinQuartic3D` struct with `vertices`, `faces`, and the 168-element
automorphism group.

EULER CHARACTERISTIC CHECK: K₄ has genus g = 3, so χ(K₄) = 2 − 2g = −4.
"""
struct KleinQuartic3D
 vertices::Vector{Vector{Float64}} # 3D points in S³ ⊂ R⁴ (we use R⁴ here)
 faces::Vector{Vector{Int}} # triangular mesh
 automorphisms::Vector{Matrix{Float64}} # 168 elements of PSL(2,7) acting on R⁴
 euler_characteristic::Int # expected -4
 genus::Int # expected 3
end

"""
 stereographic_S3_to_R3(p4) → Vector{Float64}

Stereographic projection from S³ ⊂ R⁴ to R³ (projecting from the north pole
(0,0,0,1)). Points at the north pole map to infinity, so we add a small offset.
"""
function stereographic_S3_to_R3(p4::Vector{Float64})
 x, y, z, w = p4
 denom = 1.0 - w
 abs(denom) < 1e-15 && return [0.0, 0.0, 0.0] # collapse near-infinity to origin
 return [x / denom, y / denom, z / denom]
end

"""
 embed_klein_quartic_in_S3(; n_theta=14, n_phi1=42, epsilon=0.3) → KleinQuartic3D

Sample the Klein quartic as the Milnor fibre of z₁³ + z₂⁴ = ε inside S³.

The Milnor fibre is a smooth genus-3 surface with 168 symmetries. We parametrise:
- z₁ = r · e^{iφ₁}, where r ∈ [0, 1], r² = cos²θ
- z₂ = √(1−r²) · e^{iφ₂}, where 1−r² = sin²θ
- Constraint: z₁³ + z₂⁴ = ε ⇒ r³ · e^{3iφ₁} + (1−r²)² · e^{4iφ₂} = ε

For each (r, φ₁), we solve for φ₂ such that the constraint holds (4 branches).
"""
function embed_klein_quartic_in_S3(; n_theta::Int=14, n_phi1::Int=42, epsilon::Float64=0.3)
 vertices = Vector{Vector{Float64}}()
 # Parametric sampling
 for it in 1:n_theta
 θ = π/2 * (it - 0.5) / n_theta # θ ∈ (0, π/2)
 r1 = cos(θ)
 r2 = sin(θ)
 for ip in 1:n_phi1
 φ1 = 2π * (ip - 1) / n_phi1
 z1_cubed = r1^3 * exp(3im * φ1)
 # z2^4 = ε - z1^3
 target = epsilon - z1_cubed
 if abs(target) < 1e-15
 continue
 end
 # 4-th root of `target`, scaled by r2^4
 # We want z2 such that z2^4 = target, |z2| = r2
 # So z2 = r2 · (target/|target|)^{1/4}
 angle_target = angle(target)
 for branch in 0:3
 φ2 = (angle_target + 2π * branch) / 4
 z1 = r1 * exp(im * φ1)
 z2 = r2 * exp(im * φ2)
 # Verify constraint
 # resid = z1^3 + z2^4 - epsilon
 # (Sanity: |resid| should be ≪ ε.)
 # Pack as R⁴ vector (Re z1, Im z1, Re z2, Im z2)
 push!(vertices, [real(z1), imag(z1), real(z2), imag(z2)])
 end
 end
 end

 # Compute Euler characteristic from the genus: χ = 2 - 2g = -4 for g = 3.
 # (We don't compute a mesh Euler characteristic from `vertices` because
 # the topology of the Milnor fibre is known to be genus 3 by Milnor's
 # theorem for the (p,q) = (3,4) Brieskorn singularity.)
 genus = 3
 euler_char = 2 - 2 * genus # = -4

 # Build PSL(2,7) automorphism group as 8×8 PERMUTATION matrices acting on
 # P¹(F₇) = {∞, 0, 1, 2, 3, 4, 5, 6} (8 points, indexed 1..8).

 # Generators (verified to satisfy (2,3,7) relations):
 # S: z ↦ -1/z → perm (1 2)(3 8)(4 5)(6 7) [order 2]
 # T: z ↦ -1/(z-1) → perm (1 2 3)(4 8 6) [order 3, fixes 5,7]
 # ST → perm (2 8 7 6 5 4 3) [order 7, fixes 1]

 # These generate the FULL PSL(2,7) of order 168, acting faithfully on 8 points.
 # (Stabiliser of any point is the Borel subgroup of order 21, so the action
 # is faithful: 168/21 = 8 points.)

 # The 8×8 permutation matrices are then lifted to R⁴ by restricting to the
 # 4-dimensional subspace spanned by the S³ coordinates (Re z1, Im z1, Re z2, Im z2).
 # For the group-ACTION verification on the Klein quartic mesh, we use the 8×8
 # permutation matrices directly (the mesh vertices live in R⁴ but the group
 # action is recorded as permutations of the 8 P¹(F₇) labels).
 S_perm = zeros(Int, 8, 8)
 for (i, j) in [(1,2),(2,1),(3,8),(8,3),(4,5),(5,4),(6,7),(7,6)]
 S_perm[i, j] = 1
 end
 T_perm = zeros(Int, 8, 8)
 # T = (1 2 3)(4 8 6), fixes 5 and 7
 T_cycle = [(1,2),(2,3),(3,1),(4,8),(8,6),(6,4),(5,5),(7,7)]
 for (i, j) in T_cycle
 T_perm[i, j] = 1
 end

 # Verify (2,3,7) relations on the 8×8 permutation matrices
 I8 = Matrix{Float64}(I, 8, 8)
 S8 = Float64.(S_perm)
 T8 = Float64.(T_perm)
 err_S2 = norm(S8^2 - I8)
 err_T3 = norm(T8^3 - I8)
 err_ST7 = norm((S8 * T8)^7 - I8)
 @assert err_S2 < 1e-10 "S² ≠ I (got defect $(err_S2))"
 @assert err_T3 < 1e-10 "T³ ≠ I (got defect $(err_T3))"
 @assert err_ST7 < 1e-10 "(ST)⁷ ≠ I (got defect $(err_ST7)) — generators not (2,3,7)"

 autos_perm = psl27_full_group(S8, T8; max_order=200)

 # The mesh vertices live in R⁴; we store the 8×8 permutation matrices as
 # the automorphism group for bookkeeping (the group acts on the 8 P¹(F₇)
 # labels, not directly on the R⁴ coordinates of the Milnor-fibre mesh).
 # For an R⁴-realisation of the group, one would use the 4-dimensional
 # real representation derived from the complex 2-dim representation of
 # PSL(2,7) — but the 8-dim permutation rep is sufficient to verify the
 # group structure (order 168, (2,3,7) presentation).
 autos = autos_perm

 # Build triangular faces (simple fan triangulation between adjacent
 # (θ, φ₁) rings — purely for visualisation, not used in topology check)
 faces = Vector{Vector{Int}}()
 n_branches = 4
 for it in 1:(n_theta - 1), ip in 1:n_phi1, b in 1:n_branches
 i_curr = ((it - 1) * n_phi1 + (ip - 1)) * n_branches + b
 i_next_phi = ((it - 1) * n_phi1 + (mod1(ip + 1, n_phi1) - 1)) * n_branches + b
 i_next_theta = (it * n_phi1 + (ip - 1)) * n_branches + b
 push!(faces, [i_curr, i_next_phi, i_next_theta])
 end

 return KleinQuartic3D(vertices, faces, autos, euler_char, genus)
end

"""
 verify_psl27_orbits(K::KleinQuartic3D) → (n_orbits, orbit_sizes, info)

Verify that the 168-element PSL(2,7) group acts on P¹(F₇) = {1..8}.

Returns:
- `n_orbits`: number of distinct orbits of {1..8} under the group action
- `orbit_sizes`: sizes of the orbits
- `info`: human-readable summary

A faithful transitive PSL(2,7) action on 8 points should give a SINGLE orbit
of size 8 (PSL(2,7) acts 2-transitively on P¹(F₇)).
"""
function verify_psl27_orbits(K::KleinQuartic3D)
 n = 8 # P¹(F₇) has 8 points
 visited = falses(n)
 orbits = Vector{Vector{Int}}()
 for i in 1:n
 visited[i] && continue
 orbit = Int[]
 for g in K.automorphisms
 # g is an 8×8 permutation matrix; apply to unit vector e_i
 e_i = zeros(Float64, n)
 e_i[i] = 1.0
 v = g * e_i
 j = argmax(v) # the image of i under the permutation
 if !(j in orbit)
 push!(orbit, j)
 end
 end
 sort!(orbit)
 for j in orbit
 1 ≤ j ≤ n && (visited[j] = true)
 end
 push!(orbits, orbit)
 end
 orbit_sizes = sort(unique(length.(orbits)))
 info = "n_orbits=$(length(orbits)), orbit_sizes=$orbit_sizes, |G|=$(length(K.automorphisms))"
 return length(orbits), orbit_sizes, info
end

"""
 verify_genus_via_euler_characteristic(K::KleinQuartic3D) → (chi, expected, ok)

For a closed orientable genus-g surface, χ = 2 − 2g. For K₄ with g = 3:
χ = 2 − 6 = −4. This function returns the expected χ (stored in K) and a
boolean `ok` indicating whether the genus matches the expected value 3.

we sample may have boundary artifacts from the parametrisation. The Euler
characteristic is asserted from the analytic Milnor-fibre theorem, not
recomputed from the mesh.
"""
function verify_genus_via_euler_characteristic(K::KleinQuartic3D)
 expected_chi = 2 - 2 * 3 # genus = 3
 return (K.euler_characteristic, expected_chi, K.euler_characteristic == expected_chi)
end

"""
 dirac_spectrum_klein_quartic(K::KleinQuartic3D; n_lowest=20) → Vector{Float64}

Compute the lowest `n_lowest` eigenvalues of the Dirac operator on the Klein
quartic mesh. The Dirac operator is approximated by the graph Laplacian's
square root (since the mesh is a discrete approximation of the surface).

For a genus-3 surface, the Dirac spectrum has the following properties:
- 2^g = 8 harmonic spinors (zero modes) if Arf = 1 (the case for K₄ per §6.3.1)
- The first nonzero eigenvalue scales as 1/Area(K₄) ∝ 1/R² where R is the
 embedding radius
- For PSL(2,7)-invariant discretisation, all 8 zero modes are degenerate
"""
function dirac_spectrum_klein_quartic(K::KleinQuartic3D; n_lowest::Int=20)
 n_v = length(K.vertices)
 n_v == 0 && return Float64[]

 # Build graph Laplacian: L = D - A, where D is degree matrix, A adjacency.
 # Two vertices are adjacent if they're closer than `threshold`.
 threshold = 0.3 # tune based on sampling density
 A = zeros(Float64, n_v, n_v)
 for i in 1:n_v, j in (i + 1):n_v
 d = norm(K.vertices[i] - K.vertices[j])
 if d < threshold
 A[i, j] = 1.0
 A[j, i] = 1.0
 end
 end
 D = Diagonal(vec(sum(A, dims=2)))
 L = D - A

 # The "Dirac" operator on a graph is sqrt(L). For small graphs we can
 # compute it via eigenvalue decomposition.
 F = eigen(Hermitian(L))
 # sqrt of eigenvalues (clamp small negatives from numerical error)
 sqrt_evals = [λ > 0 ? sqrt(λ) : 0.0 for λ in F.values]
 # Return the lowest n_lowest "Dirac" eigenvalues
 return sort(sqrt_evals)[1:min(n_lowest, length(sqrt_evals))]
end


