 @printf(" = exp(2πi/%d) · exp(i·%.4f·ln(%d))\n", ch.lambda_DSI, β_imag, ch.lambda_DSI)
 @printf(" = %.6f + %.6f·i (|CF| = %.6f by construction)\n",
 real(cf), imag(cf), abs(cf))
 @printf("\n")
 @printf(" LaTeX HARDCODED value (line 425, used in honesty_calculations.py):\n")
 @printf(" CF_hard = %.4f + %.4f·i (|CF_hard| = %.6f)\n",
 cf_hardcoded_re, cf_hardcoded_im, abs(cf_hardcoded))
 @printf(" c_AB = 1 - |CF_hard| = %.6f (LaTeX eq:c-AB value: 0.02063)\n",
 c_AB_hardcoded)
 @printf("\n")
