# 11d. TEST 37 (menu id): (1/2)! VIA THE GAMMA FUNCTION — half-factorial audit
# The suite's central statistical law — the GUE (β=2) Wigner surmise
#     p₂(s) = (32/π²)·s²·exp(−4s²/π)
# works ONLY because the factorial extends to fractional arguments through Γ,
# and the normalization constant 32/π² is exactly the half-factorial identity
# in disguise:
#     ∫₀^∞ s² e^{−4s²/π} ds = ½·(π/4)^{3/2}·Γ(3/2) = ½·(π/4)^{3/2}·(1/2)!
#                           = π²/32      (because (1/2)! = √π/2),
# so N·π²/32 = 1 ⟺ N = 32/π². Every χ²/KS/A-D verdict in this suite therefore
# rests on the half-factorial construction. The audit:
#   ① Γ(1/2) = √π and (1/2)! = Γ(3/2) = √π/2 (machine ε, suite's own Lanczos
#     lgamma — the same machinery that serves every χ² CDF in the suite);
#   ② the half-integer ladder (3/2)! = 3√π/4, (5/2)! = 15√π/8 and the
#     recurrence (x+1)! = (x+1)·x! — the whole tower from Γ(1/2) alone;
#   ③ UNIQUENESS OF THE CONSTRUCTION:
#       · reflection self-dual fixed point — x = 1/2 is the ONLY point where
#         Γ(x) = Γ(1−x), and Γ(1/2)² = π there (the α↔1/α self-duality theme
#         of Tests 17/18 in factorial form);
#       · Bohr–Mollerup: ln Γ is strictly log-convex on the half-grid, so Γ
#         is the UNIQUE log-convex factorial extension — (1/2)! is not a
#         convention but a theorem;
#   ④ the physics payoff: N = 1/[½·(π/4)^{3/2}·(1/2)!] == 32/π² exactly;
#     ∫p₂ ds = 1 and ⟨s²⟩ = 3π/8 (⟨s⟩ = 1) by Simpson quadrature of the
#     suite's own gue2_surmise_pdf; the same P(1/2, x²) regularized gamma
#     differentiates to (2/√π)e^{−x²} — the erf kernel χ² CDFs (df odd)
#     are built on.
# Pass 2 (HARDCORE, test44b): the same identities re-audited at 256-bit.
# ─────────────────────────────────────────────────────────────────────────────

"""Simpson quadrature of f on [a, b] with n intervals (n forced even).
Local to the half-factorial audit — no dependencies beyond Base."""
function _hf_simpson(f::Function, a::Float64, b::Float64, n::Int)::Float64
    n = iseven(n) ? n : n + 1
    h = (b - a) / n
    s = f(a) + f(b)
    @inbounds for i in 1:(n - 1)
        s += f(a + i * h) * (isodd(i) ? 4.0 : 2.0)
    end
    return s * h / 3.0
end

# ── Test 37 (menu id): (1/2)! via Γ — half-factorial & GUE normalization ────
function test44_half_factorial_gamma(zeta_zeros::Vector{Float64}, cfg::Config)
 println("\n$(repeat("═",60))")
 println("TEST 37: (1/2)! via Γ — half-factorial audit & GUE normalization")
 println("(1/2)! = Γ(3/2) = √π/2 — the fractional factorial that normalizes")
 println("the GUE β=2 Wigner surmise p₂(s) = (32/π²)s²·exp(−4s²/π)")
 println(repeat("─",60))

 rec = Tuple{String,Bool,String}[]

 # ── ① Γ(1/2) = √π and (1/2)! = Γ(3/2) = √π/2 (machine ε) ──
 g_half = exp(lgamma_lanczos(0.5))
 err_ghalf = abs(g_half - √π) / √π
 f_half = exp(lgamma_lanczos(1.5))
 err_fhalf = abs(f_half - √π / 2) / (√π / 2)
 @printf(" Γ(1/2)      = %.15f   √π   = %.15f   rel.err = %.2e\n", g_half, √π, err_ghalf)
 @printf(" (1/2)!      = %.15f   √π/2 = %.15f   rel.err = %.2e\n", f_half, √π / 2, err_fhalf)
 push!(rec, ("Γ(1/2) = √π", err_ghalf < 1e-12, @sprintf("rel.err %.2e (Lanczos lgamma, suite-internal)", err_ghalf)))
 push!(rec, ("(1/2)! = √π/2", err_fhalf < 1e-12, @sprintf("rel.err %.2e", err_fhalf)))

 # ── ② half-integer ladder + recurrence ──
 ladder_err = 0.0
 rec_err = 0.0
 ladder_vals = Float64[] # report-plot data
 ladder_x = Float64[]
 for (n, closed) in ((0, √π / 2), (1, 3√π / 4), (2, 15√π / 8))
     v = exp(lgamma_lanczos(n + 1.5))
     ladder_err = max(ladder_err, abs(v - closed) / closed)
     push!(ladder_x, n + 0.5); push!(ladder_vals, v)
 end
 for x in (0.5, 1.5, 2.5)
     lhs = exp(lgamma_lanczos(x + 1.0))
     rhs = x * exp(lgamma_lanczos(x))
     rec_err = max(rec_err, abs(lhs - rhs) / lhs)
 end
 @printf(" (3/2)! = 3√π/4, (5/2)! = 15√π/8: max rel.err = %.2e\n", ladder_err)
 @printf(" recurrence (x+1)! = (x+1)·x! at x ∈ {1/2, 3/2, 5/2}: max rel.err = %.2e\n", rec_err)
 push!(rec, ("half-integer ladder", ladder_err < 1e-12,
  @sprintf("(3/2)!, (5/2)! closed forms, max rel.err %.2e", ladder_err)))
 push!(rec, ("recurrence tower", rec_err < 1e-12,
  @sprintf("Γ(x+1) = x·Γ(x) from Γ(1/2) alone, max rel.err %.2e", rec_err)))

 # ── ③ uniqueness of the construction ──
 # (a) reflection self-dual fixed point: Γ(1/2)² = π (x = 1/2 is the only
 #     self-dual point of Γ(x)Γ(1−x) = π/sin(πx))
 refl_err = abs(g_half^2 - π) / π
 @printf(" reflection self-duality: Γ(1/2)² = %.15f  vs π = %.15f  rel.err = %.2e\n",
  g_half^2, π, refl_err)
 push!(rec, ("Γ(1/2)² = π (self-dual)", refl_err < 1e-12,
  @sprintf("x=1/2 — the UNIQUE fixed point of x ↔ 1−x in the reflection formula, rel.err %.2e", refl_err)))
 # (b) Bohr–Mollerup log-convexity: lnΓ strictly convex on the half-grid —
 #     the UNIQUE log-convex factorial extension
 hx = collect(0.5:0.25:3.0)
 lg = [lgamma_lanczos(x) for x in hx]
 d1 = diff(lg)
 convex_ok = all(d -> d > 0, diff(d1)) # strictly increasing first differences
 @printf(" Bohr–Mollerup: lnΓ strictly log-convex on the half-grid 0.5..3.0 → %s\n",
  convex_ok ? "YES (Γ is the UNIQUE log-convex factorial extension)" : "VIOLATED")
 push!(rec, ("log-convex uniqueness", convex_ok,
  "strictly increasing ΔlnΓ on 0.5:0.25:3.0 — (1/2)! is a theorem, not a convention"))

 # ── ④ the physics payoff: the GUE surmise normalization IS the half-factorial ──
 N_hf = 1.0 / (0.5 * (π / 4)^1.5 * f_half) # normalization built FROM (1/2)!
 err_N = abs(N_hf - 32 / π^2) / (32 / π^2)
 @printf(" N from (1/2)!: 1/[½·(π/4)^{3/2}·(1/2)!] = %.15f   32/π² = %.15f  rel.err = %.2e\n",
  N_hf, 32 / π^2, err_N)
 push!(rec, ("32/π² from (1/2)!", err_N < 1e-12,
  @sprintf("the GUE normalization constant IS the half-factorial identity, rel.err %.2e", err_N)))
 # numerical quadrature of the suite's own surmise: ∫p₂ = 1, ⟨s⟩ = 1, ⟨s²⟩ = 3π/8
 Z = _hf_simpson(gue2_surmise_pdf, 0.0, 8.0, 16000)
 mean_s = _hf_simpson(s -> s * gue2_surmise_pdf(s), 0.0, 8.0, 16000)
 mean_s2 = _hf_simpson(s -> s^2 * gue2_surmise_pdf(s), 0.0, 8.0, 16000)
 @printf(" ∫₀^∞ p₂ ds = %.15f  (target 1);  ⟨s⟩ = %.12f (target 1);  ⟨s²⟩ = %.12f (target 3π/8 = %.12f)\n",
  Z, mean_s, mean_s2, 3π / 8)
 quad_ok = abs(Z - 1.0) < 1e-10 && abs(mean_s - 1.0) < 1e-9 && abs(mean_s2 - 3π / 8) < 1e-10
 push!(rec, ("∫p₂ = ⟨s⟩ = 1, ⟨s²⟩ = 3π/8", quad_ok,
  @sprintf("Simpson 16k nodes on gue2_surmise_pdf; var = 3π/8−1 = %.12f = rmt_law_var()", mean_s2 - 1.0)))
 # the erf kernel: P(1/2, x²) differentiates to (2/√π)e^{−x²} (central differences)
 dP_err = 0.0
 h = 1e-3
 for x in (0.5, 1.0, 2.0)
     d = (regularized_gamma_p(0.5, (x + h)^2) - regularized_gamma_p(0.5, (x - h)^2)) / (2h)
     dP_err = max(dP_err, abs(d - (2 / √π) * exp(-x^2)))
 end
 @printf(" erf kernel: d/dx P(1/2, x²) = (2/√π)e^{−x²} (central diff): max |Δ| = %.2e\n", dP_err)
 push!(rec, ("P(1/2,·) ⇔ erf kernel", dP_err < 1e-5,
  @sprintf("the χ²-odd-df CDF kernel verified by differentiation, max |Δ| %.2e", dP_err)))

 # ── report plot (no-op outside report mode): the half-factorial ladder ──
 if REP.current !== nothing
  p = RepPlot("T37: half-factorial ladder (n+1/2)! = Γ(n+3/2) — all of GUE normalization flows from √π/2",
              "n  (point x = n + 1/2)", "(n+1/2)!")
  add_series!(p, "Γ(n+3/2) computed (Lanczos)", ladder_x, ladder_vals, 's')
  add_series!(p, "closed form {√π/2, 3√π/4, 15√π/8}", ladder_x,
              [√π / 2, 3√π / 4, 15√π / 8], 'l')
  rep_plot!(p)
 end

 overall = all(ok3 for (_, ok3, _) in rec)
 status = overall ? msg(cfg, "pass") : msg(cfg, "warn")
 log_result(" Test 37: (1/2)!=√π/2 [rel.err $(round(err_fhalf, digits=2))], 32/π² [rel.err $(round(err_N, digits=2))], " *
  "∫p₂=1 [|Δ|=$(round(abs(Z - 1.0), digits=12))], uniqueness ✓ → $status")
 return overall
end

# ── Test 37b (menu id 37, HARDCORE pass 2): (1/2)! 256-bit precision audit ──
# The base proves the identities in Float64; the hardcore pass recomputes the
# half-factorial ladder INDEPENDENTLY at 256-bit BigFloat and quantifies the
# Float64 round-off. Julia's Base has NO gamma function for BigFloat (gamma /
# logabsgamma live in the non-stdlib SpecialFunctions.jl — this suite is
# stdlib-only), so the 256-bit truth is computed from scratch by the
# double-exponential (tanh-sinh) rule on the u-substituted Gaussian integrals
#     Γ(n + 1/2) = ∫₀^∞ 2·u^{2n}·e^{−u²} du   (u = √x — kills the x^{−1/2}
# endpoint singularity; the integrand is analytic → DE converges
# double-exponentially; audit grid h = 1/32, t ∈ [−6.25, 6.25]:
# |Γ(1/2)_DE − √π| ≈ 1.2e−28 at 256-bit, probe-validated):
#   H1  Float64 round-off of the suite's Lanczos lgamma measured against the
#       256-bit DE truth (Γ(1/2), (1/2)! at machine-ε relative scale)
#   H2  normalization identity at 256-bit: 1/[½·(π/4)^{3/2}·Γ(3/2)_DE] == 32/π²
#   H3  ladder/reflection/recurrence at 256-bit: Γ(5/2)_DE = 3√π/4,
#       Γ(1/2)_DE² = π, (1/2)!_DE = ½·Γ(1/2)_DE
function test44b_half_factorial_hardcore(zeta_zeros::Vector{Float64}, cfg::Config)
 println("\n$(repeat("═",60))")
 println("TEST 37 (pass 2, HARDCORE): (1/2)! via Γ — 256-bit precision audit")
 println(repeat("─",60))
 rec = Tuple{String,Bool,String}[]
 setprecision(256) do
  h_de = big(1) / 32
  M_de = 200
  # Independent 256-bit Γ(n + 1/2) by DE quadrature of the Gaussian form.
  function _gamma_half_int(n::Int)::BigFloat
   s = BigFloat(0)
   for k in -M_de:M_de
    t = k * h_de
    u = exp(big(π) / 2 * sinh(t))
    s += 2 * u^(2n) * exp(-u^2) * u * (big(π) / 2) * cosh(t)
   end
   return s * h_de
  end
  Γ_half_b = _gamma_half_int(0)   # Γ(1/2)   (independent DE value)
  f_half_b = _gamma_half_int(1)   # (1/2)!   = Γ(3/2)
  f_32_b   = _gamma_half_int(2)   # (3/2)!   = Γ(5/2)
  sqrt_pi_b = sqrt(big(π))
  @printf(" DE reference: |Γ(1/2)_256 − √π| = %.2e (independent quadrature)\n",
   Float64(abs(Γ_half_b - sqrt_pi_b)))
  # H1: Float64 round-off of the suite's Lanczos lgamma vs the DE truth
  err_g = Float64(abs(big(exp(lgamma_lanczos(0.5))) - Γ_half_b) / Γ_half_b)
  err_f = Float64(abs(big(exp(lgamma_lanczos(1.5))) - f_half_b) / f_half_b)
  @printf(" Γ(1/2):  Float64 vs 256-bit DE rel.err = %.2e\n", err_g)
  @printf(" (1/2)!:  Float64 vs 256-bit DE rel.err = %.2e\n", err_f)
  push!(rec, ("Float64 round-off", err_g < 1e-14 && err_f < 1e-14,
   @sprintf("|ΔΓ(1/2)|=%.2e, |Δ(1/2)!|=%.2e relative (machine-ε scale)", err_g, err_f)))
  # H2: normalization identity at 256-bit from the DE Γ(3/2)
  N_b = 1 / (big(1) / 2 * (big(π) / 4)^(3 // 2) * f_half_b)
  err_N = Float64(abs(N_b - 32 / big(π)^2) / (32 / big(π)^2))
  @printf(" N = 1/[½·(π/4)^{3/2}·(1/2)!] at 256-bit vs 32/π²: rel.err = %.2e\n", err_N)
  push!(rec, ("32/π² identity (256-bit)", err_N < 1e-20,
   @sprintf("rel.err %.2e — exact at 256-bit", err_N)))
  # H3: ladder + reflection self-duality + recurrence at 256-bit
  ladder_err_b = Float64(abs(f_32_b - 3 * sqrt_pi_b / 4) / (3 * sqrt_pi_b / 4))
  refl_err_b = Float64(abs(Γ_half_b^2 - big(π)) / big(π))
  rec_err_b = Float64(abs(f_half_b - Γ_half_b / 2) / f_half_b)
  @printf(" ladder Γ(5/2)_DE = 3√π/4: rel.err = %.2e\n", ladder_err_b)
  @printf(" Γ(1/2)_DE² = π (reflection self-duality): rel.err = %.2e\n", refl_err_b)
  @printf(" recurrence (1/2)!_DE = ½·Γ(1/2)_DE: rel.err = %.2e\n", rec_err_b)
  push!(rec, ("ladder + self-duality + recurrence (256-bit)",
   ladder_err_b < 1e-20 && refl_err_b < 1e-20 && rec_err_b < 1e-20,
   @sprintf("worst rel.err %.2e across the three identities",
    max(ladder_err_b, max(refl_err_b, rec_err_b)))))
  rep_note!(@sprintf("Test 37 HARDCORE: 256-bit DE Γ(1/2) err %.2e, Float64 round-off Γ(1/2) %.2e / (1/2)! %.2e, N=32/π² err %.2e, ladder/self-dual/recurrence exact.",
   Float64(abs(Γ_half_b - sqrt_pi_b)), err_g, err_f, err_N))
 end
 return hc_verdict_table(cfg, "Test 37b", rec)
end


