function try_plot_convergence(zeta_zeros::Vector{Float64}, cfg::Config)
 Ns = Int[]; n = 50
 while n ≤ length(zeta_zeros)
 push!(Ns, n); n *= 2
 end
 bNs = [compute_bN(zeta_zeros, N) for N in Ns]

 println("\n [Plot: b(N) convergence]")
 println(" N b(N)")
 for (N, bN) in zip(Ns, bNs)
 bar_len = round(Int, min(bN, 5.0) * 8)
 bar = repeat("#", bar_len)
 @printf(" %-10d %.4f %s\n", N, bN, bar)
 end

 if PLOTS_AVAILABLE && cfg.plot
 try
 Plots.gr()
 p = Plots.plot(Ns, bNs, lw=2, label="b(N)",
 xlabel="N", ylabel="b(N)",
 title="Objection 1: b(N) Convergence",
 xscale=:log10, yscale=:log10,
 marker=:circle, ms=4,
 legend=:topright)
 Plots.plot!(Ns, 3.0 ./ sqrt.(Float64.(Ns)), lw=2, ls=:dash, label="O(1/sqrt(N)) reference")
 out = joinpath(cfg.output_dir, "objection1_convergence.png")
 mkpath(cfg.output_dir)
 Plots.savefig(p, out)
 println(" Plot saved: $out")
 catch e
 println(" [Plots.jl save failed: $e]")
 end
 end
end

function try_plot_gue_spacing(zeta_zeros::Vector{Float64}, cfg::Config)
 sp = normalized_spacings(zeta_zeros)

 println("\n [Plot: GUE spacing histogram]")
 nbins = 20
 s_max = 4.0
 counts = Vector{Int}(undef, nbins)
 fill!(counts, 0)
 for s in sp
 s ≥ s_max && continue
 bin = min(Int(floor(s / s_max * nbins)) + 1, nbins)
 counts[bin] += 1
 end
 max_count = maximum(counts)
 for i in 1:nbins
 lo = (i-1) * s_max / nbins
 hi = i * s_max / nbins
 gue_v = gue_pdf(Float64((lo + hi) / 2))
 gue_bar = round(Int, gue_v * length(sp) * (s_max / nbins) / max_count * 30)
 emp_bar = round(Int, counts[i] / max_count * 30)
 @printf(" [%.1f,%.1f) %4d %s | GUE %s\n", lo, hi, counts[i],
 repeat("#", emp_bar), repeat(".", gue_bar))
 end

 if PLOTS_AVAILABLE && cfg.plot
 try
 Plots.gr()
 s_range = range(0, 4, length=200)
 gue_vals = [gue_pdf(s) for s in s_range]
 p = Plots.histogram(sp, bins=range(0, 4, length=30), label="empirical",
 xlabel="s", ylabel="p(s)",
 title="Objection 2: GUE Spacing Distribution",
 xlims=(0, 4), alpha=0.7, legend=:topright)
 Plots.plot!(s_range, gue_vals, lw=2, label="GUE: (pi*s/2)*exp(-pi*s^2/4)", color=:red)
 out = joinpath(cfg.output_dir, "objection2_gue_spacing.png")
 mkpath(cfg.output_dir)
 Plots.savefig(p, out)
 println(" Plot saved: $out")
 catch e
 println(" [Plots.jl save failed: $e]")
 end
 end
end

function try_plot_decay(zeta_zeros::Vector{Float64}, cfg::Config)
 Ns = Int[]; n = 50
 while n ≤ length(zeta_zeros)
 push!(Ns, n); n *= 2
 end
 bNs = [compute_bN(zeta_zeros, N) for N in Ns]

 println("\n [Plot: Decay rate — log-log]")
 logN = log.(Float64.(Ns))
 logb = log.(bNs)
 a, b, R2, _, _ = linreg(logN, logb)
 @printf(" Slope = %.4f (expected -0.5) | R² = %.4f\n", b, R2)
 for (lN, lb) in zip(logN, logb)
 fit_val = a + b * lN
 @printf(" log(N)=%6.2f data=%+.4f fit=%+.4f\n", lN, lb, fit_val)
 end

 if PLOTS_AVAILABLE && cfg.plot
 try
 Plots.gr()
 p = Plots.scatter(logN, logb, label="data",
 xlabel="log(N)", ylabel="log(b(N))",
 title="Objection 3: Decay Rate (slope = $(round(b,digits=4)))",
 legend=:topright, ms=5)
 Plots.plot!(logN, a .+ b .* logN, lw=2, label="fit (R²=$(round(R2,digits=4)))", color=:red)
 Plots.plot!(logN, log(3.0) .- 0.5 .* logN, lw=2, ls=:dash, label="slope = -0.5", color=:green)
 out = joinpath(cfg.output_dir, "objection3_decay_rate.png")
 mkpath(cfg.output_dir)
 Plots.savefig(p, out)
 println(" Plot saved: $out")
 catch e
 println(" [Plots.jl save failed: $e]")
 end
 end
end

