function save_report(cfg::Config)
 ts = Dates.format(Dates.now(), "yyyy-mm-dd_HH-MM-SS")
 fname = "ab_cloud_v20_verify_report_$(ts).txt"
 mkpath(cfg.output_dir)
 fpath = joinpath(cfg.output_dir, fname)

 open(fpath, "w") do f
 println(f, "AB-Cloud Verification Report")
 println(f, "Generated: $(Dates.now())")
 println(f, "Author: Isaev Iskhak Khamzatovich")
 println(f, "ORCID: 0009-0003-7299-0701")
 println(f, "DOI: 10.5281/zenodo.21825394")
 println(f, "Repo: https://github.com/wild8highlander/research-papers")
 println(f, "Config: zeros=$(cfg.zeros_count), source=$(cfg.source), lang=$(cfg.lang)")
 println(f, " n_checkpoints=$(cfg.n_checkpoints), n_monotone=$(cfg.n_monotone)")
 println(f, " n_bootstrap=$(cfg.n_bootstrap), chi2_bins=$(cfg.chi2_bins)")
 println(f, " stability_fraction=$(cfg.stability_fraction), stability_threshold=$(cfg.stability_threshold)")
 println(f, " bN_pass_threshold=$(cfg.bN_pass_threshold)")
 println(f, " power_law_tolerance=$(cfg.power_law_tolerance)")
 println(f, " slope_ci_tolerance=$(cfg.slope_ci_tolerance)")
 println(f, " gue_matrix_size=$(cfg.gue_matrix_size), gue_matrix_seed=$(cfg.gue_matrix_seed)")
 println(f, " ad_sample_cap=$(cfg.ad_sample_cap)")
 println(f, " rmt_spacing_law=$(rmt_law_name())")
 println(f, " rmt_cdf_table=$(RMT_TABLE_ON[] ? "on" : "off") " *
 "(32768-pt interp, max|ΔF|=$(_RMT_TABLE_MAXERR[]))")
 println(f, " t31_lmax=$(cfg.t31_lmax)")
 println(f, " rigidity_L_values=$(cfg.rigidity_L_values)")
 println(f, " rigidity_n_windows=$(cfg.rigidity_n_windows) (Sigma^2)")
 println(f, " rigidity_n_windows_d3=$(cfg.rigidity_n_windows_d3) (Delta_3)")
 println(f, " rigidity_n_grid=$(cfg.rigidity_n_grid)")
 println(f, "")
 println(f, "EMBEDDED DATASET:")
 println(f, " 50,000 real Riemann zeta zeros (Odlyzko official table)")
 println(f, " Source: https://www-users.cse.umn.edu/~odlyzko/zeta_tables/zeros6")
 println(f, " First zero: 14.134725142 (the first non-trivial zero of zeta(s))")
 println(f, "")
 println(f, "AB-CLOUD VERIFICATION SUITE — FEATURES")
 println(f, "")
 println(f, "1. Offset-Gram matching for correct sub-sample b(N) computation")
 println(f, "2. Non-mutating KS/CvM/chi-squared tests (sort copy, not in-place)")
 println(f, "3. Exact chi-squared CDF via regularized incomplete gamma (any df)")
 println(f, "4. KS asymptotic p-value (correct Kolmogorov formula)")
 println(f, "5. Anderson-Darling, 2-sample KS, Sigma^2(L), Delta_3(L) tests")
 println(f, "6. Simulated GUE reference matrix for empirical comparison")
 println(f, "7. Embedded 50,000 real Riemann zeta zeros (self-contained)")
 println(f, "8. Bilingual EN/RU output")
 println(f, "9. AB-cloud Hofstadter Hamiltonian with topological vortices")
 println(f, "10. Dirac string construction for correct AB flux")
 println(f, "11. Fractional vortex charges (Byers-Yang theorem compliance)")
 println(f, "12. Periodic Dirac string for torus geometry")
 println(f, "13. Choptyuk–Isaev particle dynamics formulas")
 println(f, "14. Full execution log capture (tee stdout to report)")
 println(f, "")
 println(f, "MATHEMATICAL FINDINGS (not bugs):")
 println(f, " - Convergence rate alpha ~ 0.19 != 0.5: b(N) decays as N^{-0.19}, not N^{-0.5}.")
 println(f, " This is consistent with b(N) ~ C/log(N) behaviour.")
 println(f, " - GUE spacing rejection for low-T zeros: EXPECTED (GUE is asymptotic).")
 println(f, " - Spectral rigidity Delta_3(L) shows ~97% relative error vs GUE at large L,")
 println(f, " consistent with the paper's own full_verification.json output.")
 println(f, "")

 # FULL EXECUTION LOG (everything tee-captured from stdout) ──
 captured = String(take!(STDOUT_CAPTURE))
 println(f, repeat("=", 60))
 println(f, "FULL EXECUTION LOG — captured stdout (tee of every println / @printf)")
 println(f, "Purpose: see exactly what each test computed, where WARNs come from,")
 println(f, " and what numbers lie behind each PASS/WARN verdict.")
 println(f, "Captured bytes: $(length(captured))")
 println(f, repeat("=", 60))
 print(f, captured)
 if !isempty(captured) && !endswith(captured, "\n")
 println(f, "")
 end
 println(f, repeat("=", 60))
 println(f, "END OF FULL EXECUTION LOG")
 println(f, repeat("=", 60))
 println(f, "")

 # FULL COMPUTATION LOG ── every log_comp() call captured ──
 comp_text = get_comp_log()

 # ── Mirror the full logs into the run's FINAL_REPORT folder ──
 # (2026-08-29 user spec: "итоговый отчёт ... собрал все репорты и логи и
 # шаги выполнения всех тестов в отдельную последнюю папку"). The per-run
 # FINAL_REPORT dir is created here; rep_finalize_run() fills in the master
 # report + per-test copies afterwards. Guarded: reporting may be off.
 if REP.enabled && !isempty(REP.run_dir)
 try
 fdir_logs = joinpath(REP.run_dir, "FINAL_REPORT", "logs")
 mkpath(fdir_logs)
 open(joinpath(fdir_logs, "full_execution_log.txt"), "w") do f
 write(f, "FULL EXECUTION LOG — tee of every println/@printf during run_all_tests\n")
 write(f, "Captured bytes: $(length(captured))\n\n")
 write(f, captured)
 end
 open(joinpath(fdir_logs, "computation_log.txt"), "w") do f
 write(f, "FULL COMPUTATION LOG — every log_comp() call during run_all_tests\n\n")
 write(f, comp_text)
 end
 catch e
 @printf(" REPORT WARN (FINAL_REPORT logs): %s\n", sprint(showerror, e))
 end
 end

 println(f, repeat("=", 60))
 println(f, "FULL COMPUTATION LOG — every log_comp() call captured during run_all_tests")
 println(f, "Purpose: see EVERY computation made (Hamiltonian builds, eigvals, ⟨r⟩,")
 println(f, " KS, A², Σ², Δ₃, MC ensemble, two-pass results, α-sweep iterations).")
 println(f, "Captured bytes: $(length(comp_text))")
 println(f, repeat("=", 60))
 print(f, comp_text)
 if !isempty(comp_text) && !endswith(comp_text, "\n")
 println(f, "")
 end
 println(f, repeat("=", 60))
 println(f, "END OF FULL COMPUTATION LOG")
 println(f, repeat("=", 60))
 println(f, "")

 # ── Existing summary section (Test N: ... → PASS / WARN lines) ──
 println(f, repeat("=", 60))
 println(f, "SUMMARY — one-line per-test verdicts (results_log)")
 println(f, repeat("=", 60))
 for line in results_log
 println(f, line)
 end
 println(f, repeat("=", 60))
 end
 println(fmt(cfg, "saving"; file=fpath))
end

