 @printf(" 50. GUE tol very loose: %.4f (|r - R_GUE| < tol → SOFT FAIL)\n", cfg.ab_gue_tol_very_loose)
 @printf(" 51. byte quant tolerance: %.4f (|Delta r| < tol → robust)\n", cfg.ab_byte_tol)
 @printf(" 52. n_bytes (RNG entropy): %d (default 200_000)\n", cfg.ab_n_bytes)
 @printf(" 53. byte RNG seed: %d\n", cfg.ab_byte_seed)
 @printf(" 54. eigs_per_seed (K(t)): %d (0=auto, >0 enables per-seed averaging)\n", cfg.ab_eigs_per_seed)
 @printf(" 55. K(t) t-values: %s (t grid for K form factor)\n", format_float_list(cfg.ab_K_t_values))
 @printf(" 56. R2 s-values: %s (s grid for pair correlation)\n", format_float_list(cfg.ab_R2_s_values))
 @printf(" 57. K smooth window: %d (smoothing window for K(t))\n", cfg.ab_K_smooth_window)
 @printf(" 58. Nv list (secondary): %s (vortex counts for 2nd pass; default [2])\n",
 format_int_list(cfg.ab_nv_list_secondary))
 println(" 59. Report generation: ", cfg.rep_enabled ? "ON" : "OFF")
 println(" 60. Report dir: ", cfg.rep_root)
 println(" 61. Plot dpi: ", cfg.rep_dpi)
 println(" 62. GIF animation: ", cfg.rep_gif ? "ON" : "OFF")
 println(" 63. Plot formats: ", join(cfg.rep_plot_formats, ","))
 println(" 64. Report formats: ", join(cfg.rep_report_formats, ","))
 println(" 65. PHYSICS LAB: experiment configurations (72×72 lab matrix default; 's' inside = all parameters)")
 @printf(" 66. W_max (disorder cap Tests 32/33/36): %.2f (W_eff = min(W, W_max); user spec ≤ 1.0)\n", cfg.ab_W_max)
 @printf(" 67. Test 36 pass-1 ⟨r⟩ sample target: %d eigenvalues\n", cfg.ab37_n_eigs_pass1)
 @printf(" 68. Test 36 pass-2 ⟨r⟩ sample target: %d eigenvalues\n", cfg.ab37_n_eigs_pass2)
 println(" 69. Test 32 comparison-row W (q=0.3 row): ",
 isnan(cfg.ab_W_cmp) ? "follow primary" : @sprintf("%.2f (cap %.2f)", cfg.ab_W_cmp, cfg.ab_W_max))
 println(" 70. Test 32 comparison-row Nv: ",
 cfg.ab_nv_cmp == 0 ? "follow primary" : string(cfg.ab_nv_cmp),
 "  (vortex-DENSITY lever for the fractional-q row)")
 println(" 71. HARDCORE realization floor (pass-2 b-variants, Tests 15–35): ", cfg.ab_hc_nreal)
 println(" 72. Third SERIES pass for Tests 19/29/31 (19c/29c/31c real report series): ",
 cfg.ab_run_third_pass ? "ON" : "OFF")
 println("\n Enter number to change, or 'q' to return:")

 # prompt was printed twice (copy-paste artifact).
 print(" > ")
 answer = strip(readline())

 # EOF guard — closed/exhausted stdin must not redraw this
 # menu forever.
 if isempty(answer)
 empty_cfg_reads += 1
 empty_cfg_reads >= 50 && (println("\nNo input on stdin (EOF) — leaving config menu."); break)
 continue
 end
 empty_cfg_reads = 0

 # a typo like "10k" in a numeric field threw ArgumentError and
 # killed the whole program; now reported and the menu redraws.
 try
 if answer == "q" || answer == "й"
 break
 elseif answer == "1"
 print(" New zeros count [current=$(cfg.zeros_count)]: ")
 v = strip(readline()); !isempty(v) && (cfg.zeros_count = parse(Int, v))
 elseif answer == "2"
 println(" Available: embedded, auto, 50k, 500k, 2M, highT, zeros6, csv")
 print(" New source [current=$(cfg.source)]: ")
 v = strip(readline()); !isempty(v) && (cfg.source = v)
 elseif answer == "3"
 print(" New data dir [current=$(cfg.data_dir)]: ")
 v = strip(readline()); !isempty(v) && (cfg.data_dir = v)
 elseif answer == "4"
 print(" New lang (en/ru) [current=$(cfg.lang)]: ")
 v = strip(readline()); v in ["en", "ru"] && (cfg.lang = v)
 elseif answer == "5"
 print(" New checkpoints [current=$(cfg.n_checkpoints), 0=auto]: ")
 v = strip(readline()); !isempty(v) && (cfg.n_checkpoints = parse(Int, v))
 elseif answer == "6"
 print(" New monotone checks [current=$(cfg.n_monotone)]: ")
 v = strip(readline()); !isempty(v) && (cfg.n_monotone = parse(Int, v))
 elseif answer == "7"
 print(" New bootstrap samples [current=$(cfg.n_bootstrap)]: ")
 v = strip(readline()); !isempty(v) && (cfg.n_bootstrap = parse(Int, v))
 elseif answer == "8"
 print(" New chi^2 bins [current=$(cfg.chi2_bins)]: ")
 v = strip(readline()); !isempty(v) && (cfg.chi2_bins = parse(Int, v))
 elseif answer == "9"
 print(" New stability fraction [current=$(cfg.stability_fraction)]: ")
 v = strip(readline()); !isempty(v) && (cfg.stability_fraction = parse(Float64, v))
 elseif answer == "10"
 print(" New stability threshold [current=$(cfg.stability_threshold)]: ")
 v = strip(readline()); !isempty(v) && (cfg.stability_threshold = parse(Float64, v))
 elseif answer == "11"
 print(" New b(N) pass threshold [current=$(cfg.bN_pass_threshold)]: ")
 v = strip(readline()); !isempty(v) && (cfg.bN_pass_threshold = parse(Float64, v))
 elseif answer == "12"
 print(" New power-law tolerance [current=$(cfg.power_law_tolerance)]: ")
 v = strip(readline()); !isempty(v) && (cfg.power_law_tolerance = parse(Float64, v))
 elseif answer == "13"
 print(" New slope CI tolerance [current=$(cfg.slope_ci_tolerance)]: ")
 v = strip(readline()); !isempty(v) && (cfg.slope_ci_tolerance = parse(Float64, v))
 elseif answer == "14"
 print(" New GUE matrix size [current=$(cfg.gue_matrix_size)]: ")
 v = strip(readline()); !isempty(v) && (cfg.gue_matrix_size = parse(Int, v))
 elseif answer == "15"
 print(" New GUE matrix seed [current=$(cfg.gue_matrix_seed)]: ")
 v = strip(readline()); !isempty(v) && (cfg.gue_matrix_seed = parse(Int, v))
 elseif answer == "16"
 print(" New AD sample cap [current=$(cfg.ad_sample_cap)]: ")
 v = strip(readline()); !isempty(v) && (cfg.ad_sample_cap = parse(Int, v))
 elseif answer == "17"
 cfg.plot = !cfg.plot
 println(" Plot generation: $(cfg.plot ? "ON" : "OFF")")
 elseif answer == "18"
 println(" Enter L-values separated by commas, spaces, or semicolons.")
 println(" Example: 2, 5, 10, 20, 50, 100, 140")
 print(" New L-values [current=$(format_l_values(cfg.rigidity_L_values))]: ")
 v = strip(readline())
 !isempty(v) && try
 new_vals = parse_l_values(v)
 println(" Parsed $(length(new_vals)) L-values: $(format_l_values(new_vals))")
 # Sanity warning: if max(L) approaches the GUE-ref unfolded length,
 # the GUE side of Tests 13/14 will return NaN. Recommend a bigger matrix.
 ref_len_estimate = floor(Int, cfg.gue_matrix_size * 0.8) # ≈ (1 - 2·trim_frac)·N
 if maximum(new_vals) > 0.5 * ref_len_estimate
 println(" WARNING: max(L)=$(maximum(new_vals)) is large relative to the")
 println(" GUE reference (matrix_size=$(cfg.gue_matrix_size), ≈$ref_len_estimate unfolded eigvals).")
 println(" Consider increasing GUE matrix size (menu item 14) to ≥ $(ceil(Int, maximum(new_vals) / 0.6)).")
 end
 cfg.rigidity_L_values = new_vals
 catch e
 println(" ERROR: $(string(e))")
 end
 elseif answer == "19"
 println(" Build a geometric L-grid (log-uniform spacing, recommended for Σ²/Δ₃).")
 print(" L_max [current max=$(maximum(cfg.rigidity_L_values))]: ")
 v_max = strip(readline())
 print(" Number of grid intervals (≥2, default 8): ")
 v_n = strip(readline())
 !isempty(v_max) && try
