"""Physics Lab menu (config item 65 / main-menu 'l')."""
# ── LAB parameter helpers + extended parameter menu ────────────
const _LAB_DEFAULTS = NamedTuple{(:lab_L, :lab_alpha, :lab_W, :lab_q, :lab_nv,
    :lab_layout, :lab_lattice, :lab_model, :lab_pos_jitter, :lab_charge_flip,
    :lab_neutrals, :lab_seed, :lab_L3d, :lab_lbm_nx, :lab_lbm_ny, :lab_lbm_steps,
    :lab_walk_n, :lab_walk_steps, :lab_walk_alpha)}(
    (72, 0.5, 4.0, 1.0, 4, :random, :torus, :monumental, 0.0, 0.0, true, 12345,
     10, 90, 60, 150, 41, 60, 0.25))

function _lab_params_show(cfg::Config)
    println("\n ── Current LAB parameters (cfg.lab_* — used by E1-E22) ──")
    @printf("  1. Matrix size L (2D experiments): %d  → runs on a %d×%d lattice\n", cfg.lab_L, cfg.lab_L, cfg.lab_L)
    @printf("  2. Alpha (flux per plaquette): %g\n", cfg.lab_alpha)
    @printf("  3. Onsite disorder W: %g\n", cfg.lab_W)
    @printf("  4. Vortex charge q: %g\n", cfg.lab_q)
    @printf("  5. Number of vortices Nv: %d\n", cfg.lab_nv)
    println("  6. Vortex layout: ", cfg.lab_layout, "  (random | hexagonal | ring | grid | centers)")
    println("  7. Boundary: ", cfg.lab_lattice, "  (torus | open)")
    println("  8. Vortex phase model: ", cfg.lab_model, "  (monumental | dirac)")
    @printf("  9. Vortex position jitter σ: %g\n", cfg.lab_pos_jitter)
    @printf(" 10. Charge-flip probability p: %g\n", cfg.lab_charge_flip)
    println(" 11. Neutral vortices (alternating ±): ", cfg.lab_neutrals ? "ON" : "OFF")
    println(" 12. Lab RNG seed: ", cfg.lab_seed)
    println(" 13. E20 3D stack size L3d (4..16): ", cfg.lab_L3d)
    println(" 14. E21 LBM grid LX×LY: ", cfg.lab_lbm_nx, "×", cfg.lab_lbm_ny)
    println(" 15. E21 LBM steps: ", cfg.lab_lbm_steps)
    println(" 16. E22 Hadamard window N (odd): ", cfg.lab_walk_n)
    println(" 17. E22 Hadamard steps: ", cfg.lab_walk_steps)
    @printf(" 18. E22 Hadamard AB phase α: %g\n", cfg.lab_walk_alpha)
    return
end

function _lab_params_reset!(cfg::Config)
    cfg.lab_L = _LAB_DEFAULTS.lab_L; cfg.lab_alpha = _LAB_DEFAULTS.lab_alpha
    cfg.lab_W = _LAB_DEFAULTS.lab_W; cfg.lab_q = _LAB_DEFAULTS.lab_q
    cfg.lab_nv = _LAB_DEFAULTS.lab_nv; cfg.lab_layout = _LAB_DEFAULTS.lab_layout
    cfg.lab_lattice = _LAB_DEFAULTS.lab_lattice; cfg.lab_model = _LAB_DEFAULTS.lab_model
    cfg.lab_pos_jitter = _LAB_DEFAULTS.lab_pos_jitter
    cfg.lab_charge_flip = _LAB_DEFAULTS.lab_charge_flip
    cfg.lab_neutrals = _LAB_DEFAULTS.lab_neutrals; cfg.lab_seed = _LAB_DEFAULTS.lab_seed
    cfg.lab_L3d = _LAB_DEFAULTS.lab_L3d
    cfg.lab_lbm_nx = _LAB_DEFAULTS.lab_lbm_nx; cfg.lab_lbm_ny = _LAB_DEFAULTS.lab_lbm_ny
    cfg.lab_lbm_steps = _LAB_DEFAULTS.lab_lbm_steps
    cfg.lab_walk_n = _LAB_DEFAULTS.lab_walk_n; cfg.lab_walk_steps = _LAB_DEFAULTS.lab_walk_steps
    cfg.lab_walk_alpha = _LAB_DEFAULTS.lab_walk_alpha
    println("  LAB parameters reset to launch defaults (72×72, α=1/2, W=4, q=1, Nv=4, random/torus/monumental).")
    return
end

# soft sanity hint: on a :torus the flux-quantisation constraint α·L ∈ ℤ must hold
# (same condition build_ab_cloud_hamiltonian asserts)
function _lab_torus_hint(cfg::Config)
    cfg.lab_lattice == :torus || return
    aL = cfg.lab_alpha * cfg.lab_L
    abs(aL - round(aL)) < 1e-9 && return
    println("  NOTE: α·L = ", aL, " — on a :torus the build asserts α·L ∈ ℤ.",
            " Adjust α/L (items 1-2) or switch boundary to :open (item 7),", 
            " otherwise experiments on this combination will report an AssertionError.")
    return
end

"""Extended LAB parameter menu: every lab knob in one place.
Mirrors the main config menu UX: number + new value, EOF-safe, typo-safe."""
function lab_params_menu!(cfg::Config)
    reads = 0
    while true
        _lab_params_show(cfg)
        println("\n Enter number to change, 'r' reset all to defaults, 'b' back:")
        print(" > ")
        answer = strip(readline())
        if isempty(answer)
            reads += 1
            reads >= 50 && (println("\nNo input (EOF) — leaving lab parameters."); return)
            continue
        end
        reads = 0
        try
            if answer == "b" || answer == "и" || answer == "q" || answer == "й"
                return
            elseif answer == "r" || answer == "к"
                _lab_params_reset!(cfg)
            elseif answer == "1"
                print(" New matrix size L [current=$(cfg.lab_L), 4..200]: ")
                v = strip(readline()); !isempty(v) || continue
                cfg.lab_L = clamp(parse(Int, v), 4, 200)
                _lab_torus_hint(cfg)
            elseif answer == "2"
                print(" New alpha [current=$(cfg.lab_alpha), 0..1]: ")
                v = strip(readline()); !isempty(v) || continue
                cfg.lab_alpha = clamp(parse(Float64, v), 0.0, 1.0)
                _lab_torus_hint(cfg)
            elseif answer == "3"
                print(" New onsite disorder W [current=$(cfg.lab_W), 0..50]: ")
                v = strip(readline()); !isempty(v) || continue
                cfg.lab_W = clamp(parse(Float64, v), 0.0, 50.0)
            elseif answer == "4"
                print(" New vortex charge q [current=$(cfg.lab_q), 0.01..5]: ")
                v = strip(readline()); !isempty(v) || continue
                cfg.lab_q = clamp(parse(Float64, v), 0.01, 5.0)
            elseif answer == "5"
                print(" New vortex count Nv [current=$(cfg.lab_nv), 0..12]: ")
                v = strip(readline()); !isempty(v) || continue
                cfg.lab_nv = clamp(parse(Int, v), 0, 12)
            elseif answer == "6"
                print(" New layout random|hexagonal|ring|grid|centers [current=$(cfg.lab_layout)]: ")
                v = strip(readline()); !isempty(v) || continue
                s = Symbol(lowercase(startswith(v, ":") ? v[2:end] : v))
                if s in (:random, :hexagonal, :ring, :grid, :centers)
                    cfg.lab_layout = s
                else
                    println("  Unknown layout — kept $(cfg.lab_layout)")
                end
            elseif answer == "7"
                print(" New boundary torus|open [current=$(cfg.lab_lattice)]: ")
                v = strip(readline()); !isempty(v) || continue
                s = Symbol(lowercase(startswith(v, ":") ? v[2:end] : v))
                if s in (:torus, :open)
                    cfg.lab_lattice = s
                    _lab_torus_hint(cfg) # switching to torus can break α·L ∈ ℤ
                else
                    println("  Unknown boundary — kept $(cfg.lab_lattice)")
                end
            elseif answer == "8"
                print(" New phase model monumental|dirac [current=$(cfg.lab_model)]: ")
                v = strip(readline()); !isempty(v) || continue
                s = Symbol(lowercase(startswith(v, ":") ? v[2:end] : v))
                if s in (:monumental, :dirac)
                    cfg.lab_model = s
                else
                    println("  Unknown model — kept $(cfg.lab_model)")
                end
            elseif answer == "9"
                print(" New position jitter σ [current=$(cfg.lab_pos_jitter), 0..5]: ")
                v = strip(readline()); !isempty(v) || continue
                cfg.lab_pos_jitter = clamp(parse(Float64, v), 0.0, 5.0)
            elseif answer == "10"
                print(" New charge-flip probability p [current=$(cfg.lab_charge_flip), 0..1]: ")
                v = strip(readline()); !isempty(v) || continue
                cfg.lab_charge_flip = clamp(parse(Float64, v), 0.0, 1.0)
            elseif answer == "11"
                print(" Neutral vortices ON/OFF [current=$(cfg.lab_neutrals ? "ON" : "OFF")]: ")
                v = lowercase(strip(readline()))
                if v in ("on", "1", "true", "да", "вкл")
                    cfg.lab_neutrals = true
                elseif v in ("off", "0", "false", "нет", "выкл")
                    cfg.lab_neutrals = false
                end
            elseif answer == "12"
                print(" New lab RNG seed [current=$(cfg.lab_seed)]: ")
                v = strip(readline()); !isempty(v) || continue
                cfg.lab_seed = parse(Int, v)
            elseif answer == "13"
                print(" New 3D stack size L3d [current=$(cfg.lab_L3d), 4..16 — dense eig memory]: ")
                v = strip(readline()); !isempty(v) || continue
                cfg.lab_L3d = clamp(parse(Int, v), 4, 16)
            elseif answer == "14"
                print(" New LBM grid \"LX LY\" [current=$(cfg.lab_lbm_nx) $(cfg.lab_lbm_ny), each 20..300]: ")
                v = strip(readline()); !isempty(v) || continue
                parts = split(v)
                if length(parts) == 2
                    cfg.lab_lbm_nx = clamp(parse(Int, parts[1]), 20, 300)
                    cfg.lab_lbm_ny = clamp(parse(Int, parts[2]), 20, 300)
                else
                    println("  Need two numbers, e.g. \"120 80\"")
                end
            elseif answer == "15"
                print(" New LBM steps [current=$(cfg.lab_lbm_steps), 20..1000]: ")
                v = strip(readline()); !isempty(v) || continue
                cfg.lab_lbm_steps = clamp(parse(Int, v), 20, 1000)
            elseif answer == "16"
                print(" New Hadamard window N [current=$(cfg.lab_walk_n), odd, 21..201]: ")
                v = strip(readline()); !isempty(v) || continue
                n = parse(Int, v); cfg.lab_walk_n = clamp(isodd(n) ? n : n + 1, 21, 201)
            elseif answer == "17"
                print(" New Hadamard steps [current=$(cfg.lab_walk_steps), 10..400]: ")
                v = strip(readline()); !isempty(v) || continue
                cfg.lab_walk_steps = clamp(parse(Int, v), 10, 400)
            elseif answer == "18"
                print(" New Hadamard AB phase α [current=$(cfg.lab_walk_alpha), 0..0.5]: ")
                v = strip(readline()); !isempty(v) || continue
                cfg.lab_walk_alpha = clamp(parse(Float64, v), 0.0, 0.5)
            else
                println("  No such parameter (1-18).")
            end
        catch err
            err isa InterruptException && (println("\n^C — interrupted."); continue)
            println("  Invalid value (", sprint(showerror, err), ") — parameter kept.")
        end
    end
end

function physics_lab_menu!(cfg::Config)
    _lab_register!()
    _lab_register_e19plus!()
    lab_reads = 0
    while true
        println("\n════════════════ PHYSICS LAB — experiment configurations ════════════════")
        @printf("  Lab defaults: %d×%d | α=%g | W=%g | q=%g | Nv=%d | %s | %s | %s | seed=%d\n",
                cfg.lab_L, cfg.lab_L, cfg.lab_alpha, cfg.lab_W, cfg.lab_q, cfg.lab_nv,
                cfg.lab_layout, cfg.lab_lattice, cfg.lab_model, cfg.lab_seed)
        println("  Select an experiment to see its full description and run it:")
        for e in LAB_EXPS
            @printf("  E%-2d. %s\n        └ %s\n", e.id - 100, e.title, e.about)
        end
        println("  a.  Run ALL experiments sequentially (writes reports for each)")
        println("  s.  Lab parameter settings — matrix size, α, W, vortices, … (applies to all runs)")
        println("  v.  View current lab parameters")
        println("  r.  Reset lab parameters to launch defaults (72×72)")
        println("  q.  Return to previous menu")
        print(" > ")
        answer = strip(readline())
        lab_reads += 1
        if isempty(answer)
            lab_reads >= 50 && (println("\nNo input (EOF) — leaving lab."); return)
            continue
        end
        lab_reads = 0
        try
            if answer == "q" || answer == "й"
                return
            elseif answer == "s" || answer == "ы" # extended parameter menu
                lab_params_menu!(cfg)
                continue
            elseif answer == "v" || answer == "м" # quick view
                _lab_params_show(cfg)
                continue
            elseif answer == "r" || answer == "к" # reset
                _lab_params_reset!(cfg)
                continue
            elseif answer == "a" || answer == "ф"
                for e in LAB_EXPS
                    println("\n▶ E", e.id - 100, ": ", e.title)
                    _lab_run!(e, cfg)
                end
                # FINAL_REPORT: gather every E1–E22 report/log into one last
                # folder (user spec 2026-08-29: "добавить и в лабораторию")
                rep_finalize_run("Physics Lab — all experiments E1–E22")
                continue
            end
            n = parse(Int, answer)
            e = findfirst(x -> x.id == 100 + n, LAB_EXPS)
            e === nothing && (println("  No such experiment (1-$(length(LAB_EXPS)))."); continue)
            exp = LAB_EXPS[e]
            println("\n─── E$(n): $(exp.title) ───")
            println(exp.detail)
 # the prompt now exposes the parameter menu before the run
            print("  Run: [Enter]=current lab settings / s=change parameters / q=cancel ")
            ok = strip(readline())
            ok == "q" && continue
            ok in ("s", "ы") && lab_params_menu!(cfg)
            _lab_run!(exp, cfg)
        catch err
            err isa InterruptException && (println("\n^C — interrupted."); continue)
            println("  ERROR: ", sprint(showerror, err))
        end
    end
end

function _lab_run!(e::LabExp, cfg::Config)
    rep_begin!(e.id, e.title)
    out = rep_tee_stdout() do
 # echo the effective lab parameter block (also lands in the report log)
        @printf("LAB PARAMETERS: L=%d α=%g W=%g q=%g Nv=%d layout=:%s lattice=:%s model=:%s σ=%g flip=%g neutrals=%s seed=%d L3d=%d lbm=%dx%d×%d walk N=%d steps=%d α=%g\n",
                cfg.lab_L, cfg.lab_alpha, cfg.lab_W, cfg.lab_q, cfg.lab_nv, cfg.lab_layout,
                cfg.lab_lattice, cfg.lab_model, cfg.lab_pos_jitter, cfg.lab_charge_flip,
                cfg.lab_neutrals, cfg.lab_seed, cfg.lab_L3d, cfg.lab_lbm_nx, cfg.lab_lbm_ny,
                cfg.lab_lbm_steps, cfg.lab_walk_n, cfg.lab_walk_steps, cfg.lab_walk_alpha)
        e.runner(cfg)
    end
    rt = REP.current
    if rt !== nothing
 # (rep_auto_plots! retired 2026-08-31 — experiments without an
        # explicit RepPlot, e.g. E19's pure-heatmap output, now report
        # "no series plots" instead of a scraped-junk curve)
        rt.headline = last_log_line()
        rep_finish!(e.id, "DONE", last_log_line())
    end
    return
end


