"""Grayscale→color heatmap PNG from a Float64 matrix (values auto-scaled)."""
function write_heatmap_png(path::String, M::AbstractMatrix{<:Real}; cols::Symbol = :jet)
    Hs, Ws = size(M)
    lo, hi = minimum(M), maximum(M)
    span = max(hi - lo, 1e-12)
    img = Array{UInt8,3}(undef, Hs, Ws, 3)
    for y in 1:Hs, x in 1:Ws
        t = clamp((M[y, x] - lo) / span, 0.0, 1.0)
        r, g, b = if cols == :jet
            (round(Int, 255 * clamp(1.5 - abs(4t - 3), 0, 1)),
             round(Int, 255 * clamp(1.5 - abs(4t - 2), 0, 1)),
             round(Int, 255 * clamp(1.5 - abs(4t - 1), 0, 1)))
        else # gray
            (round(Int, 255t), round(Int, 255t), round(Int, 255t))
        end
        # FIX 2026-08-31: write row 1 of M to the BOTTOM image row — the
        # SVG heatmap (and every spatial map convention) puts matrix row 1
        # at the bottom; the PNG used to render the same matrix VERTICALLY
        # FLIPPED relative to its own SVG twin.
        img[Hs - y + 1, x, 1] = UInt8(r); img[Hs - y + 1, x, 2] = UInt8(g); img[Hs - y + 1, x, 3] = UInt8(b)
    end
    return write_png(path, img, REP.dpi > 0 ? REP.dpi : 600)
end

"""SVG heatmap (colored rect grid, full Unicode labels)."""
function write_heatmap_svg(path::String, M::AbstractMatrix{<:Real}, title::String,
                           xlabel::String, ylabel::String)
    Hs, Ws = size(M)
    lo, hi = minimum(M), maximum(M); span = max(hi - lo, 1e-12)
    s = IOBuffer()
    print(s, "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"640\" height=\"560\" font-family=\"Arial\">\n<text x=\"320\" y=\"24\" text-anchor=\"middle\" font-size=\"18\">$(_svg_esc(title))</text>\n")
    cell = 480 / max(Hs, Ws)
    ox, oy = 60, 50
    for y in 1:Hs, x in 1:Ws
        t = clamp((M[y, x] - lo) / span, 0.0, 1.0)
        r = round(Int, 255 * clamp(1.5 - abs(4t - 3), 0, 1))
        g = round(Int, 255 * clamp(1.5 - abs(4t - 2), 0, 1))
        b = round(Int, 255 * clamp(1.5 - abs(4t - 1), 0, 1))
        print(s, "<rect x=\"$(round(ox + (x-1)*cell, digits=1))\" y=\"$(round(oy + (Hs-y)*cell, digits=1))\" width=\"$(round(cell+0.3,digits=2))\" height=\"$(round(cell+0.3,digits=2))\" fill=\"rgb($r,$g,$b)\"/>\n")
    end
    print(s, "<text x=\"320\" y=\"540\" text-anchor=\"middle\" font-size=\"14\">$(_svg_esc(xlabel))</text>\n")
    print(s, "<text x=\"20\" y=\"290\" text-anchor=\"middle\" font-size=\"14\" transform=\"rotate(-90 20 290)\">$(_svg_esc(ylabel))</text>\n</svg>\n")
    open(path, "w") do f
        write(f, String(take!(s)))
    end
    return path
end

# ── E19: AB cloud construction & 2D spatial distribution ───────────────
function lab_e19(cfg::Config)
    L = cfg.lab_L
    println("\n AB-cloud construction & 2D spatial distribution (L=$L, α=$(cfg.lab_alpha), $(cfg.lab_nv) vortices):")
    c = lab_cfg(cfg; L = L)
    H = build_ab_cloud_hamiltonian(c)
    Hc = Matrix(H)
    site_amp = vec([sum(abs.(Hc[:, i])) for i in 1:(L * L)])       # per-site coupling mass
    E = eigen(Hermitian(Hc))
    psi0 = abs2.(E.vectors[:, 1]); psi_mid = abs2.(E.vectors[:, size(E.vectors, 2) ÷ 2])
    println("   ground state E₀ = ", round(E.values[1], digits = 4),
            " | mid-band E = ", round(E.values[size(E.vectors, 2) ÷ 2], digits = 4))
    @printf("   IPR(ψ₀) = %.4f, IPR(mid) = %.4f (1/N = %.4f)\n",
            sum(psi0 .^ 2), sum(psi_mid .^ 2), 1.0 / (L * L))
    M1 = reshape(site_amp, L, L)'; M2 = reshape(psi0, L, L)'; M3 = reshape(psi_mid, L, L)'
    slugbase = joinpath(REP.run_dir, "test_119_abcloud_2d", "plots")
    mkpath(slugbase)
    write_heatmap_png(joinpath(slugbase, "cloud_coupling_2d.png"), M1)
    write_heatmap_svg(joinpath(slugbase, "cloud_coupling_2d.svg"), M1,
        "AB cloud: per-site coupling mass", "x", "y")
    write_heatmap_png(joinpath(slugbase, "ground_state_density.png"), M2)
    write_heatmap_svg(joinpath(slugbase, "ground_state_density.svg"), M2,
        "|ψ₀|² ground-state density", "x", "y")
    write_heatmap_png(joinpath(slugbase, "midband_density.png"), M3)
    write_heatmap_svg(joinpath(slugbase, "midband_density.svg"), M3,
        "|ψ|² mid-band density", "x", "y")
    println("   heatmaps → ", slugbase, "/*.png|svg")
    rep_note!("The AB cloud IS the spatial texture of hopping magnitudes/phases generated by " *
              "vortices + uniform α flux. The coupling-mass map shows the cloud's spatial " *
              "distribution; ψ₀ hugs vortex cores (type-II like), the mid-band state is " *
              "extended (IPR ≈ 1/N) — the two-component structure the monograph relies on.")
    return
end

# ── E20: AB cloud in 3D — vortex lines & layer distribution ────────────
function lab_e20(cfg::Config)
 # 3D stack size from the LAB menu; hard cap 16 — the dense matrix
    # is (L³)×(L³) complex, 16³ = 4096 already costs ~1 GB and minutes of eig.
    L = clamp(cfg.lab_L3d, 4, 16)
    cfg.lab_L3d > 16 && println("   (lab_L3d=$(cfg.lab_L3d) clamped to 16 — dense $(L^3)×$(L^3) eig memory limit)")
    println("\n AB cloud in 3D: vortex LINES through a $(L)×$(L)×$(L) lattice:")
    H3 = h3d_build(L; alpha = cfg.lab_alpha, tz = 1.0,
                   vlines = [(L / 2, L / 2, +1.0), (L / 4, 3L / 4, -1.0)], W = 0.0)
    deg = vec([sum(abs.(H3[:, i])) for i in 1:(L^3)])
    Mz = reshape(deg, L, L, L)
 # write_heatmap_png needs a 2D matrix — squeeze the z axis
    sl = dropdims(sum(Mz, dims = 3); dims = 3)
    println("   mean per-site coupling = ", round(mean(deg), digits = 2),
            " | fluctuation = ", round(std(deg), digits = 2))
    @printf("   line sites (top-5%% coupling) carry %.1f%% of total weight\n",
            100 * sum(sort(deg, rev = true)[1:max(1, length(deg) ÷ 20)]) / sum(deg))
    E = eigen(Hermitian(H3))
    @printf("   spectrum: E ∈ [%.3f, %.3f], ⟨r⟩(bulk) = %.4f\n",
            E.values[1], E.values[end],
            mean_adjacent_spacing_ratio(central_band_eigs(sort(E.values), 0.6))[1])
    p = RepPlot("E20: 3D cloud — coupling vs layer (z)", "layer z", "mean |H| per site")
    add_series!(p, "layer mass", collect(1.0:Float64(L)), [mean(Mz[:, :, k]) for k in 1:L], 'l')
    rep_plot!(p)
    slugbase = joinpath(REP.run_dir, "test_120_abcloud_3d", "plots")
    mkpath(slugbase)
    write_heatmap_png(joinpath(slugbase, "cloud_3d_xy_projection.png"), sl)
    write_heatmap_svg(joinpath(slugbase, "cloud_3d_xy_projection.svg"), sl,
        "3D cloud: xy projection (z-integrated coupling)", "x", "y")
    println("   maps → ", slugbase)
    rep_note!("3D generalization: vortices become LINES along z (straight Dirac strings). " *
              "The cloud's xy projection localizes near the lines; layer masses are uniform " *
              "— translational invariance along the string. ⟨r⟩ in 3D tests GUE universality " *
              "of the line-coupled Hofstadter stack.")
    return
end

# ── E21: REAL 2D hydrodynamics of e⁻/e⁺ jets (D2Q9 LBM) ───────────────
function lab_e21(cfg::Config)
    println("\n 2D hydrodynamics of e⁻/e⁺ jets — D2Q9 Lattice-Boltzmann, vortex obstacle:")
 # LBM grid/steps from the LAB menu (clamped to keep runtime bounded)
    LX = clamp(cfg.lab_lbm_nx, 20, 300)
    LY = clamp(cfg.lab_lbm_ny, 20, 300)
    NSTEPS = clamp(cfg.lab_lbm_steps, 20, 1000)
    w = (4 / 9, 1 / 9, 1 / 9, 1 / 9, 1 / 9, 1 / 36, 1 / 36, 1 / 36, 1 / 36)
    ex = (0, 1, 0, -1, 0, 1, -1, -1, 1); ey = (0, 0, 1, 0, -1, 1, 1, -1, -1)
 # opp[7]/opp[9] were self-opposites — NW(−1,+1) must reflect to
    # SE(+1,−1) and vice versa (was opp[7]=7, opp[9]=9).
    opp = (1, 4, 5, 2, 3, 8, 9, 6, 7)
    q_v = 0.3
    cx, cy, R = LX ÷ 3, LY ÷ 2, max(4.0, round(Float64, min(LX, LY) / 10))   # vortex-pair obstacle region (scales with grid)
    f = [fill(0.0, LY, LX) for _ in 1:9]
    nf = [fill(0.0, LY, LX) for _ in 1:9]
    for k in 1:9, y in 1:LY, x in 1:LX
        f[k][y, x] = w[k] * (1.0 + 3 * 0.1 * ex[k])
    end
    inobst(x, y) = (x - cx)^2 + (y - cy)^2 < R^2 ||
                   (x - (2 * LX ÷ 3))^2 + (y - cy)^2 < R^2 # two flux tubes (v+ and v−)
    moments(f) = begin
        rho = sum(f); ux = sum(f[k][y, x] * ex[k] for k in 1:9)
        uy = sum(f[k][y, x] * ey[k] for k in 1:9)
        return rho, ux, uy
    end
    en_series = Float64[]
    for step in 1:NSTEPS
        # collide (BGK) + force (jet drive), then stream
        for y in 1:LY, x in 1:LX
            inobst(x, y) && continue
            rho = sum(f[k][y, x] for k in 1:9)
            rho > 1e-9 || continue
            ux = sum(f[k][y, x] * ex[k] for k in 1:9) / rho
            uy = sum(f[k][y, x] * ey[k] for k in 1:9) / rho
 # low-Mach safety valve. BGK's quadratic feq turns NEGATIVE
            # once |u| ≳ 0.3 and the scheme explodes exponentially (measured:
            # density ~1e75 after 150 steps). The raw drive added ~0.02/step of
            # vertical momentum with no ceiling — the old aliasing bug simply
            # masked this by zeroing everything at step 2. Clamp the velocity
            # used inside feq (jets saturate at Ma ≈ 0.17), weaken the drive
            # 10×, and relax at τ=0.8 (ν=0.1) for a wide stability margin.
            ux = clamp(ux, -0.1, 0.1); uy = clamp(uy, -0.1, 0.1)
            drive = (x < LX ÷ 4) ? (mod1(y, LY) ≤ LY ÷ 2 ? 1 : -1) : 0  # e⁻ up, e⁺ down at inlet
            for k in 1:9
                eu = ex[k] * ux + ey[k] * uy
                feq = w[k] * rho * (1 + 3eu + 4.5eu^2 - 1.5(ux^2 + uy^2))
                f[k][y, x] += (feq - f[k][y, x]) / 0.8 + w[k] * 3 * drive * 0.002 * ey[k]
            end
        end
        for k2 in 1:9, y2 in 1:LY, x2 in 1:LX
            nf[k2][y2, x2] = 0.0
        end
 # streaming now uses half-way BOUNCE-BACK at the flux tubes
        # (no-slip, mass-conserving) instead of dropping the incoming
        # population, which used to leak mass every step.
        for y in 1:LY, x in 1:LX
            inobst(x, y) && continue
            for k in 1:9
                xs = mod1(x - ex[k], LX); ys = mod1(y - ey[k], LY)
                if inobst(xs, ys)
                    # reflect the population that would enter the tube:
                    # standard bounce-back off the post-collision state
                    nf[k][y, x] = k == 1 ? f[1][y, x] : f[opp[k]][y, x]
                else
                    nf[k][y, x] = f[k][ys, xs]
                end
            end
        end
 # Julia's `f = nf` copies
        # the REFERENCE, so from step 2 on `nf` and `f` aliased one buffer —
        # the `nf .= 0` wipe then erased the just-collided state and the
        # streaming read saw all zeros (density range [0.000, 0.000], max
        # |v_x| = 0.000 forever). Swap the two buffers instead.
        f, nf = nf, f
 # f is a vector of 9 matrices — sum |f| over all layers' sites
        step % 50 == 0 && push!(en_series, sum(sum(abs, m) for m in f) / (LX * LY))
    end
    rho_map = [sum(f[k][y, x] for k in 1:9) for y in 1:LY, x in 1:LX]
    vx_map = [(sum(f[k][y, x] * ex[k] for k in 1:9)) / max(rho_map[y, x], 1e-9) for y in 1:LY, x in 1:LX]
    vor = [vx_map[min(y + 1, LY), x] - vx_map[max(y - 1, 1), x] for y in 1:LY, x in 1:LX]
 # report the FLUID density only — obstacle sites hold no fluid
    rho_fluid = [rho_map[y, x] for y in 1:LY, x in 1:LX if !inobst(x, y)]
    @printf("   grid %dx%d, %d steps; density range [%.3f, %.3f]; max |v_x| = %.3f\n",
            LX, LY, NSTEPS, minimum(rho_fluid), maximum(rho_fluid), maximum(abs.(vx_map)))
    println("   wake vorticity extrema = ±", round(maximum(abs.(vor)), digits = 3),
            " (Kármán-like shedding behind flux tubes)")
    slugbase = joinpath(REP.run_dir, "test_121_hydro_jets", "plots")
    mkpath(slugbase)
    write_heatmap_png(joinpath(slugbase, "hydro_density.png"), rho_map)
    write_heatmap_svg(joinpath(slugbase, "hydro_density.svg"), rho_map,
        "e⁻/e⁺ jets: density (two flux-tube obstacle)", "x", "y")
    write_heatmap_png(joinpath(slugbase, "hydro_vorticity.png"), vor)
    write_heatmap_svg(joinpath(slugbase, "hydro_vorticity.svg"), vor,
        "vorticity ω_z (wake)", "x", "y")
    p = RepPlot("E21: total population vs step (jet feed)", "step/50", "Σf")
    add_series!(p, "Σf", collect(1.0:length(en_series)), en_series, 'l')
    rep_plot!(p)
    println("   maps → ", slugbase)
    rep_note!("A true Navier–Stokes solver (D2Q9 LBM, BGK collision) drives two counter-" *
              "streams — electron and positron jets — past two AB flux tubes. Vorticity " *
              "maps show the Kármán-type wake shed from the tubes; circulation around each " *
              "tube is quantized by construction (the flux q enters through the no-slip " *
              "core), connecting classical wake hydrodynamics to the quantum circulation " *
              "Γ = h/m per flux quantum.")
    return
end

# ── E22: quantum Hadamard walk with AB phases ──────────────────────────
function lab_e22(cfg::Config)
    println("\n Quantum Hadamard walk on a 2D lattice (coin ⊗ shift, AB phase per column):")
 # walk parameters from the LAB menu (N made odd — coin needs a center site)
    N = clamp(isodd(cfg.lab_walk_n) ? cfg.lab_walk_n : cfg.lab_walk_n + 1, 21, 201)
    STEPS = clamp(cfg.lab_walk_steps, 10, 400)
    alpha = clamp(cfg.lab_walk_alpha, 0.0, 0.5)
    # coin space {↑,↓}; walker in an N×N window; AB phase e^{2πiαx} on the ↑ branch
    ψ = Dict{Tuple{Int,Int,Int,Int},ComplexF64}()  # (x,y,cx,cy) — coin product state (|↑↑>,|↑↓>,|↓↑>,|↓↓>)
    ψ[(0, 0, 0, 0)] = 1.0
    H2 = [1 1; 1 -1] ./ sqrt(2)
    function step!(ψ)
        out = Dict{Tuple{Int,Int,Int,Int},ComplexF64}()
        for (key, amp) in ψ
            (x, y, c1, c2) = key
            for nc1 in 0:1, nc2 in 0:1
                a = amp * H2[nc1 + 1, c1 + 1] * H2[nc2 + 1, c2 + 1]
                dx = nc1 == 0 ? 1 : -1
                dy = nc2 == 0 ? 1 : -1
                ph = (nc1 == 0) ? exp(2π * im * alpha * (x + dx)) : 1.0
                nk = (mod(x + dx, N) - N ÷ 2, mod(y + dy, N) - N ÷ 2, nc1, nc2)
                out[nk] = get(out, nk, 0.0) + a * ph
            end
        end
        return out
    end
    widths = Float64[]
    probs_each = Vector{Dict{Tuple{Int,Int},Float64}}()
    for s in 1:STEPS
        ψ = step!(ψ)
        if s % 12 == 0
            P = Dict{Tuple{Int,Int},Float64}()
            for ((x, y, _, _), a) in ψ
                P[(x, y)] = get(P, (x, y), 0.0) + abs2(a)
            end
            mx = sum(abs2(k[1]) * v for (k, v) in P)
            my = sum(abs2(k[2]) * v for (k, v) in P)
            push!(widths, sqrt(mx + my))
            s >= STEPS - 24 && push!(probs_each, P)
        end
    end
    println("   α = $alpha (magnetic phase per ↑-branch column): ballistic spreading width:")
    for (k, wv) in enumerate(widths)
        println("   step ", (k) * 12, ": σ = ", round(wv, digits = 2))
    end
    p = RepPlot("E22: Hadamard walk width vs steps (α=$alpha)", "step", "σ (rms)")
    add_series!(p, "σ(t)", collect(12.0:12:STEPS), widths, 'l')
    rep_plot!(p)
    if !isempty(probs_each)
        M = zeros(N, N)
        for ((x, y), v) in probs_each[end]
            M[mod1(x + N ÷ 2 + 1, N), mod1(y + N ÷ 2 + 1, N)] = v
        end
        slugbase = joinpath(REP.run_dir, "test_122_hadamard", "plots")
        mkpath(slugbase)
        write_heatmap_png(joinpath(slugbase, "hadamard_final_probs.png"), M)
        write_heatmap_svg(joinpath(slugbase, "hadamard_final_probs.svg"), M,
            "Hadamard walk P(x,y) after $STEPS steps (α=$alpha)", "x", "y")
        println("   probability map → ", slugbase)
    end
    rep_note!("A discrete-time quantum walk is a discretized Dirac equation: the Hadamard " *
              "coin plays the role of the spinor rotation, the shift is the light-cone " *
              "propagation. Adding the AB phase e^{2πiαx} on one coin branch inserts a " *
              "synthetic magnetic field — the walk exhibits Hofstadter-type interference; " *
              "σ(t) grows ballistically (∝t) until quantum-interference backscattering " *
              "slows it, a clean non-relativistic-to-relativistic crossover demo.")
    return
end

