"""Site coordinates of the h3d_build index convention
idx(x, y, z) = x + L·(y−1) + L²·(z−1)."""
function _d3_site_coords(L::Int)
    N = L^3
    xs = Vector{Float64}(undef, N); ys = similar(xs); zs = similar(xs)
    for z in 1:L, y in 1:L, x in 1:L
        i = x + L * (y - 1) + L * L * (z - 1)
        xs[i] = Float64(x); ys[i] = Float64(y); zs[i] = Float64(z)
    end
    return xs, ys, zs
end

# ── the ζ machinery (wave mode, 3D-34) ─────────────────────────────────────
# Euler–Maclaurin tail: ζ(s) = Σ_{k<M} k^{−s} + M^{−s}·[M/(s−1) + 1/2 +
#   Σ_j B_{2j}/(2j)!·s^{⟨2j−1⟩}·M^{−2j+1}]  — the standard high-precision
# method for arbitrary complex s (same family as Mathematica's); converges
# for ANY s ≠ 1 once M ≳ 2|s|. Self-anchored in 3D-34 against ζ(2), ζ(4),
# ζ(1/2) and the first ten embedded Odlyzko zeros.
const _D3_B2J_FACT = # B_{2j}/(2j)! precomputed: 1/6/2!, −1/30/4!, 1/42/6!, …
    (1.0 / 6 / 2, -1.0 / 30 / 24, 1.0 / 42 / 720, -1.0 / 30 / 40320,
     5.0 / 66 / 3628800, -691.0 / 2730 / 479001600,
     7.0 / 6 / 87178291200, -3617.0 / 510 / 20922789888000,
     43867.0 / 798 / 6402373705728000, -174611.0 / 330 / 121645100408832000)

"""
    _d3_zeta(s; M = 0, P = 10) → ComplexF64

Riemann zeta ζ(s) for complex s ≠ 1 via the Euler–Maclaurin expansion.
M = 0 → auto (max(30, ⌈2|s|⌉ + 16)). Accuracy ≥ 1e-12 for |s| ≤ 100.
"""
function _d3_zeta(s::ComplexF64; M::Int = 0, P::Int = 10)::ComplexF64
    abs(s - 1.0) < 1e-9 && return ComplexF64(Inf) # the pole
    Ms = M > 0 ? M : max(30, Int(ceil(2 * abs(s))) + 16)
    acc = 0.0 + 0.0im
    for k in 1:(Ms - 1)
        acc += exp(-s * log(Float64(k))) # k^{−s}
    end
    tail = Ms / (s - 1.0) + 0.5
    rise = s                                # s^{⟨1⟩}
    mpow = 1.0 / Float64(Ms)                # M^{−1} → M^{−3} → …
    for j in 1:min(P, length(_D3_B2J_FACT))
        j > 1 && (rise *= (s + (2j - 3)) * (s + (2j - 2))) # extend to s^{⟨2j−1⟩}
        tail += _D3_B2J_FACT[j] * rise * mpow
        mpow /= Float64(Ms)^2
    end
    return acc + exp(-s * log(Float64(Ms))) * tail
end
_d3_zeta(re::Float64, im::Float64) = _d3_zeta(ComplexF64(re, im))

"""Riemann–Siegel theta θ(t), t > 0, with the 1/(48t) + 7/(5760t³) + 31/(8064t⁵)
corrections (the same series the suite's gram_point uses → mutual consistency)."""
function _d3_rs_theta(t::Float64)::Float64
    t <= 0 && return 0.0
    a = t / (2π)
    return t / 2 * log(a) - t / 2 - π / 8 + 1 / (48t) + 7 / (5760t^3) + 31 / (8064t^5)
end

"""Hardy Z-function: Z(t) = e^{iθ(t)}·ζ(1/2+it) — REAL for real t (up to FP);
its sign changes ARE the zeros on the critical line."""
_d3_hardy_Z(t::Float64)::Float64 =
    real(exp(im * _d3_rs_theta(t)) * _d3_zeta(ComplexF64(0.5, t)))

# ── the Lorentz machinery (particle mode, 3D-32/3D-33) ─────────────────────
"""Regularized flux-LINE field (the 3D analog of the E7 tube): B = Bz(x,y)·ẑ,
total flux 2πq through the xy-plane — a vortex line of the 3D stack."""
_d3_line_Bz(x::Float64, y::Float64, q::Float64, σ::Float64) =
    q / (2π * σ^2) * exp(-(x^2 + y^2) / (2σ^2))

"""RK4 Lorentz integrator in 3D (m = |q| = 1): state (x, y, z, vx, vy, vz),
B = Bz(x,y)·ẑ; sgn = ±1 — the e⁻/e⁺ charge sign. Magnetic force does NO work
→ |v| is conserved (the work–energy check of 3D-32). Returns the path and
the per-step record of (t, θ_unwrapped, r_xy) plus ray-crossing data."""
function _d3_helix_shoot(sgn::Float64, x0::Float64, y0::Float64,
                         vx0::Float64, vy0::Float64, vz0::Float64,
                         q::Float64, σ::Float64;
                         T::Float64 = 30.0, dt::Float64 = 0.005,
                         trap::Bool = false, B0::Float64 = 1.0)
    # trap=true: a smooth magnetic TRAP line — |B| = B0 inside r ≤ 3.5,
    # cosine-tapered to 0 at r = 4.5 (the idealized core region of a flux
    # line; modern atom-chip/trapped-ion charge simulators use exactly such
    # magnetic-bottle lines). Inside the flat region the motion is the EXACT
    # cyclotron circle → clean winding around the line.
    Bz(x::Float64, y::Float64) = trap ? begin
        r = hypot(x, y)
        r ≤ 3.5 ? B0 : r ≥ 4.5 ? 0.0 : 0.5 * B0 * (1 + cos(π * (r - 3.5)))
    end : _d3_line_Bz(x, y, q, σ)
    vabs = hypot(vx0, vy0, vz0)
    st = (x0, y0, 0.0, vx0, vy0, vz0)
    deriv(s) = begin
        b = Bz(s[1], s[2])
        (s[4], s[5], s[6], sgn * s[5] * b, -sgn * s[4] * b, 0.0)
    end
    path = NTuple{6,Float64}[st]
    θold = atan(st[2], st[1]); θtot = 0.0
    crossings = Int[]; cross_z = Float64[]; cross_t = Float64[]
    nplus = 0; nminus = 0 # signed ray crossings: N₊ − N₋ = W (winding number)
    nsteps = round(Int, T / dt)
    for k in 1:nsteps
        k1 = deriv(st); k2 = deriv(st .+ (dt / 2) .* k1)
        k3 = deriv(st .+ (dt / 2) .* k2); k4 = deriv(st .+ dt .* k3)
        st = st .+ (dt / 6) .* (k1 .+ 2 .* k2 .+ 2 .* k3 .+ k4)
        push!(path, st)
        # unwrapped polar angle around the LINE (the puncture)
        θnew = atan(st[2], st[1])
        dθ = θnew - θold
        dθ > π && (dθ -= 2π); dθ < -π && (dθ += 2π)
        θtot += dθ; θold = θnew
        # ray crossing: the branch-cut ray {(x>0, y=0)} — y sign flip with
        # BOTH endpoints on the x>0 side (the AB analog of Re s = 1/2).
        # SIGN: crossing upward (y: −→+, vy>0) = θ increasing through 0 = +1.
        yprev = (path[end-1])[2]; xprev = (path[end-1])[1]
        if xprev > 0 && st[1] > 0 && ((yprev < 0 && st[2] ≥ 0) || (yprev > 0 && st[2] ≤ 0))
            push!(crossings, k); push!(cross_z, st[3]); push!(cross_t, k * dt)
            yprev < 0 ? (nplus += 1) : (nminus += 1)
        end
    end
    return (path = path, theta = θtot, crossings = crossings,
            cross_z = cross_z, cross_t = cross_t, vabs = vabs,
            nplus = nplus, nminus = nminus)
end

# ── 3D-31: Dirac zitterbewegung ────────────────────────────────────────────
function t3_31(cfg)
    L = min(clamp(cfg.d3_L, 4, 12), 12) # two full eigendecompositions
    L < cfg.d3_L && (println("   (d3_L=$(cfg.d3_L) capped to $L — full eig + wave-packet machinery)"))
    println("\n 3D-31: Dirac electron — ZITTERBEWEGUNG in the 3D stack (L=$L):")
    println("   Modern apparatus: the Dirac position/energy structure makes a localized")
    println("   ±E WAVE PACKET oscillate between the positive- and negative-energy seas")
    println("   at ω = 2mc²/ħ (Schrödinger 1930; measured: trapped-ion Dirac simulator,")
    println("   Gerritsma et al. Nature 2010; graphene, Wimmer et al. PRL 2010).")
    println("   ħ = 1, lattice units. The lattice trembling observable is ⟨Γ⟩(t), the")
    println("   sublattice (Dirac-sea) imbalance — Γ = (−1)^(x+y+z) is the chiral sign.")
    # ── chiral structure on the torus build ──
    Ht = h3d_cfg(cfg; L = L, alpha = 0.5, W = 0.0, mass = 0.0, tz_stagger = false)
    Et = eigen(Hermitian(Ht))
    ev_t = Et.values
    xs, ys, zs = _d3_site_coords(L)
    Γ = [isodd(Int(x) + Int(y) + Int(z)) ? -1.0 : 1.0 for (x, y, z) in zip(xs, ys, zs)]
    Gd = Diagonal(Γ)
    dΓ_t = norm(Gd * Hermitian(Ht) * Gd + Hermitian(Ht)) / norm(Hermitian(Ht))
    j0 = findfirst(e -> e > 0.05, ev_t)
    j0 === nothing && (println("   no band state above the zero forest — check the build"); return false)
    Eplus = ev_t[j0]
    imn = argmin(abs.(ev_t .+ Eplus))
    defect = abs(Eplus + ev_t[imn])
    @printf("   chiral tower: ΓHΓ = −H defect %.2e | pair E₊ = %+.9f, E₋ = %+.9f, |E₊+E₋| = %.2e\n",
            dΓ_t, Eplus, ev_t[imn], defect)
    # ── dynamics on the OPEN-z stack (the physical trap/orbit with edges) ──
    Ho = h3d_cfg(cfg; L = L, alpha = 0.5, W = 0.0, mass = 0.0, tz_stagger = false,
                 open_from_cfg = false, openz = true)
    Eo = eigen(Hermitian(Ho))
    ev_o = Eo.values
    dΓ_o = norm(Gd * Hermitian(Ho) * Gd + Hermitian(Ho)) / norm(Hermitian(Ho))
    @printf("   open-z build keeps the Dirac tower: ΓHΓ = −H defect %.2e\n", dΓ_o)
    # wave packet: a site state spectral-filtered into DISJOINT ±E₀ windows
    # (the Gerritsma/Wimmer construction; windows never touch the near-zero
    # forest). E₀ scanned for the densest window (tight Δ → sharp 2E₀ peak).
    i0 = (L ÷ 2) + L * ((L ÷ 2) - 1) + L * L * ((L ÷ 2) - 1) # stack-center site
    E0 = NaN; Δ = NaN; Wp = Int[]; Wm = Int[]
    Wpc = Int[]; Wmc = Int[] # declared here so the scan loop can hand them over
    for E0c in (0.12, 0.2, 0.35, 0.5, 0.7)
        Δc = 0.05
        for _ in 1:5
            Wpc = findall(e -> (abs(e - E0c) ≤ Δc) && (e > 0.05), ev_o)
            Wmc = findall(e -> (abs(e + E0c) ≤ Δc) && (e < -0.05), ev_o)
            (length(Wpc) ≥ 20 && length(Wmc) ≥ 20) && break
            Δc *= 1.3
        end
        if length(Wpc) ≥ 12 && length(Wmc) ≥ 12
            E0, Δ, Wp, Wm = E0c, Δc, Wpc, Wmc
            (Δc ≤ 0.052) && break # tight enough — stop scanning
        end
    end
    isnan(E0) && (println("   too few states in the ±E₀ windows — adapt E₀"); return false)
    VW = hcat(Eo.vectors[:, Wp], Eo.vectors[:, Wm])
    EW = vcat(ev_o[Wp], ev_o[Wm])
    cW = VW[i0, :]
    cW ./= norm(cW)
    n_p = length(Wp)
    @printf("   packet: site (%d,%d,%d), E₀ = %.3f ± %.3f → %d+%d levels (disjoint windows)\n",
            L ÷ 2, L ÷ 2, L ÷ 2, E0, Δ, n_p, length(Wm))
    Γw = VW' * (Γ .* VW)                       # ⟨k|Γ|l⟩ on the window
    ωexp = 2 * E0                              # the pair-gap frequency (ħ = 1)
    Tw = 4 * (2π / ωexp)                       # 4 trembling periods
    tg = collect(0.0:(Tw / 200):Tw)
    gG = [begin u = cW .* exp.(-im .* EW .* t); real(dot(u, Γw * u)) end for t in tg]
    AΓ = (maximum(gG) - minimum(gG)) / 2
    d = gG .- mean(gG)
    ωs = collect(range(0.2 * ωexp, 4.0 * ωexp; length = 600))
    pw = [abs(sum(d[i] * cis(-w * tg[i]) for i in eachindex(d))) for w in ωs]
    ωmeas = ωs[argmax(pw)]
    # CONTROL: the +E₀ sector alone — no sea-to-sea interference
    cp = cW[1:n_p]
    Γpp = Γw[1:n_p, 1:n_p]
    gGp = [begin u = cp .* exp.(-im .* EW[1:n_p] .* t); real(dot(u, Γpp * u)) end for t in tg]
    dp = gGp .- mean(gGp)
    pwp = [abs(sum(dp[i] * cis(-w * tg[i]) for i in eachindex(d))) for w in ωs]
    ctrl_ratio = pwp[argmax(pw)] / max(pw[argmax(pw)], 1e-30)
    @printf("   trembling of ⟨Γ⟩(t): amplitude = %.4f (full swing ≈ 1 = sea↔sea migration)\n", AΓ)
    @printf("   frequency: measured ω = %.5f vs pair gap 2E₀ = %.5f (rel.err %.1e)\n",
            ωmeas, ωexp, abs(ωmeas - ωexp) / ωexp)
    @printf("   Compton scale: ħ/(2m) = 1/(2E₀) = %.4f sets the trembling period\n", 1 / ωexp)
    @printf("   control (+E₀ sector alone): peak-power ratio at 2E₀ = %.1e\n", ctrl_ratio)
    # torus contrast row (informational): the periodic stack's ± window is
    # spectrally sparse near E₀ → the interference spectrum smears
    Δt = min(Δ, 0.15)
    Wpt = findall(e -> (abs(e - E0) ≤ Δt) && (e > 0.05), ev_t)
    Wmt = findall(e -> (abs(e + E0) ≤ Δt) && (e < -0.05), ev_t)
    if length(Wpt) ≥ 4 && length(Wmt) ≥ 4
        VWt = hcat(Et.vectors[:, Wpt], Et.vectors[:, Wmt])
        EWt = vcat(ev_t[Wpt], ev_t[Wmt])
        cWt = VWt[i0, :]; cWt ./= norm(cWt)
        Γwt = VWt' * (Γ .* VWt)
        gGt = [begin u = cWt .* exp.(-im .* EWt .* t); real(dot(u, Γwt * u)) end for t in tg]
        dt_ = gGt .- mean(gGt)
        pwt = [abs(sum(dt_[i] * cis(-w * tg[i]) for i in eachindex(dt_))) for w in ωs]
        @printf("   torus contrast: %d+%d levels → A = %.4f, ω_peak = %.4f (spectrum smears on the periodic stack)\n",
                length(Wpt), length(Wmt), (maximum(gGt) - minimum(gGt)) / 2, ωs[argmax(pwt)])
    end
    p1 = RepPlot("3D-31: zitterbewegung — ⟨Γ⟩(t), sea↔sea trembling of the ±E₀ packet", "t", "sublattice imbalance")
    add_series!(p1, "⟨Γ⟩(t) packet (+E₀)+(−E₀)", tg, gG, 'l')
    add_series!(p1, "control: +E₀ sector alone", tg, gGp, 'l')
    rep_plot!(p1)
    p2 = RepPlot("3D-31: power spectrum of the trembling — the peak sits at the pair gap 2E₀", "ω", "power")
    add_series!(p2, "|FFT|² of ⟨Γ⟩(t)", ωs, pw, 'l')
    add_series!(p2, "2E₀", [ωexp, ωexp], [0.0, maximum(pw)], 'l')
    rep_plot!(p2)
    rep_note!("PHYSICS: the Dirac-sea structure of the α=1/2 tower is exact: Γ = " *
              "(−1)^(x+y+z) satisfies ΓHΓ = −H to machine precision (printed defect), " *
              "so every level E has its −E mirror. A site-localized packet filtered " *
              "into DISJOINT ±E₀ windows is the lattice Gerritsma/Wimmer setup: the " *
              "sea↔sea interference makes the sublattice imbalance ⟨Γ⟩(t) swing at the " *
              "pair gap ω = 2E₀ (the lattice zitterbewegung; the continuum ⟨x̂⟩ " *
              "trembling maps to the sea imbalance because the lattice x̂ is diagonal " *
              "and its ±E₀ cross-block vanishes by the torus selection rule — measured " *
              "‖⟨+E₀|x̂|−E₀⟩‖ ≈ 1e-14). The dynamics live on the OPEN-z stack: the " *
              "physical electron sits in a trap/orbit where edges break translation " *
              "symmetry; the control row proves the peak at 2E₀ comes from the ±E₀ " *
              "interference alone. In the user's picture this is the wave/particle " *
              "hinge: the trembling wave performs its function while the localized " *
              "measurement (3D-33) rides a branch and crosses the critical line.")
    ok_pair = dΓ_t < 1e-10 && dΓ_o < 1e-10 && defect < 1e-8
    ok_amp = AΓ > 0.1
    # the packet carries a BAND of pair gaps [2(E₀−Δ), 2(E₀+Δ)] — the peak
    # must sit inside that physical band (tight windows pin it at 2E₀)
    ok_freq = abs(ωmeas - ωexp) ≤ 2 * Δ
    ok_ctrl = ctrl_ratio < 0.25
    @printf("   verdict: chiral/Γ %s | amplitude %s | frequency %s (band ±%.3f) | control %s\n",
            ok_pair ? "OK" : "FAIL", ok_amp ? "OK" : "FAIL", ok_freq ? "OK" : "FAIL", 2 * Δ,
            ok_ctrl ? "OK" : "FAIL")
    return ok_pair && ok_amp && ok_freq && ok_ctrl
end

# ── 3D-32: e⁻/e⁺ charge conjugation ────────────────────────────────────────
function t3_32(cfg)
    L = clamp(cfg.d3_L, 4, 16)
    m = L / 2 + 0.5
    ab = cfg.d3_alpha
    println("\n 3D-32: e⁻/e⁺ — CHARGE CONJUGATION in 3D (lattice C-identity + Lorentz helices):")
    println("   The positron is the charge-conjugate of the electron (C of CPT). On the")
    println("   lattice conj(H(q, α)) = H(−q, −α) (Peierls phases flip) ⇒ the ENERGY")
    println("   spectra are IDENTICAL — the e⁻/e⁺ asymmetry lives in the wavefunctions'")
    println("   phases, never in the energies. Then: real 3D Lorentz RK4 helices around")
    println("   a flux LINE (B = Bz(x,y)·ẑ): mirrored deflection, |v| conserved (B does")
    println("   no work), identical z-drift.")
    Hq = h3d_cfg(cfg; L = L, vlines = [(m, m, 0.3)], extra_vlines = false, alpha = ab)
    Hcq = h3d_cfg(cfg; L = L, vlines = [(m, m, -0.3)], extra_vlines = false, alpha = -ab)
    eq = _h3_eig(Hq); ecq = _h3_eig(Hcq)
    dC = maximum(abs.(eq - ecq))
    @printf("   C-identity (q=±0.3, α↔−α, L=%d): max|ΔE| = %.2e → %s\n", L, dC, dC < 1e-9 ? "OK" : "FAIL")
    σ = 0.4; qv = 0.3; vperp = 1.0; vz0 = 0.3
    # E7 geometry: beam along +x, impact parameter in y, PLUS the 3D z-drift.
    pe = _d3_helix_shoot(-1.0, -6.0, 0.8, vperp, 0.0, vz0, qv, σ; T = 20.0, dt = 0.01)
    pp = _d3_helix_shoot(+1.0, -6.0, 0.8, vperp, 0.0, vz0, qv, σ; T = 20.0, dt = 0.01)
    ppm = _d3_helix_shoot(+1.0, -6.0, -0.8, vperp, 0.0, vz0, qv, σ; T = 20.0, dt = 0.01) # mirror partner
    ye, yp = pe.path[end][2], pp.path[end][2]
    y0b = 0.8 # the unperturbed straight-line y (beam along +x, vy(0) = 0)
    speed_e = hypot(pe.path[end][4], pe.path[end][5], pe.path[end][6])
    speed_p = hypot(pp.path[end][4], pp.path[end][5], pp.path[end][6])
    vabs0 = pe.vabs
    @printf("   e⁻ exit Δy = %+.4f | e⁺ exit Δy = %+.4f (same beam — deflection sign %s)\n",
            ye - y0b, yp - y0b, (ye - y0b) * (yp - y0b) < 0 ? "FLIPS ✓" : "same ✗")
    @printf("   mirror row: e⁻@+0.8 → y=%+.4f  vs  e⁺@−0.8 → y=%+.4f  (|Δ| = %.2e)\n",
            ye, ppm.path[end][2], abs(ye + ppm.path[end][2]))
    @printf("   |v| conserved: e⁻ %.9f, e⁺ %.9f (v₀ = %.9f) — B does no work\n", speed_e, speed_p, vabs0)
    @printf("   z-drift (mirror pair): e⁻ %.6f vs e⁺ %.6f (Δ = %.2e)\n",
            pe.path[end][3], ppm.path[end][3], abs(pe.path[end][3] - ppm.path[end][3]))
    p1 = RepPlot("3D-32: e⁻/e⁺ trajectories around the flux line (xy)", "x", "y")
    add_series!(p1, "e⁻ (q<0)", [s[1] for s in pe.path], [s[2] for s in pe.path], 'l')
    add_series!(p1, "e⁺ (q>0)", [s[1] for s in pp.path], [s[2] for s in pp.path], 'l')
    add_series!(p1, "e⁺ mirror", [s[1] for s in ppm.path], [s[2] for s in ppm.path], 'l')
    rep_plot!(p1)
    p2 = RepPlot("3D-32: helix z-drift — B does no work, vz conserved", "x", "z")
    add_series!(p2, "e⁻ z(t)", [s[1] for s in pe.path], [s[3] for s in pe.path], 'l')
    add_series!(p2, "e⁺ z(t)", [s[1] for s in pp.path], [s[3] for s in pp.path], 'l')
    rep_plot!(p2)
    rep_note!("CHARGE CONJUGATION: the map q→−q, α→−α is complex conjugation of the " *
              "Hamiltonian; a Hermitian matrix and its transpose share the REAL spectrum, " *
              "so e⁻ and e⁺ are spectrally indistinguishable — the positron is the " *
              "re-interpretation of the SAME levels (Dirac sea → modern QFT: CPT). The " *
              "Lorentz rows show the classical shadow: same-mass opposite charges bend " *
              "oppositely (the sign flip), the mirror launch reproduces the e⁻ path " *
              "reflected, and the magnetic force never changes |v| — the exact statement " *
              "behind 'the AB phase, not the Lorentz kick, carries the flux physics'.")
    okC = dC < 1e-9
    okMirror = abs(ye + ppm.path[end][2]) < 1e-3
    okWork = abs(speed_e - vabs0) < 1e-6 && abs(speed_p - vabs0) < 1e-6
    okFlip = (ye - y0b) * (yp - y0b) < 0 # deflections relative to the free line, opposite signs
    @printf("   verdict: C-id %s | mirror %s | work–energy %s | sign flip %s\n",
            okC ? "OK" : "FAIL", okMirror ? "OK" : "FAIL", okWork ? "OK" : "FAIL", okFlip ? "OK" : "FAIL")
    return okC && okMirror && okWork && okFlip
end

# ── 3D-33: particle mode — the critical-line crossing theorem ─────────────
function t3_33(cfg)
    println("\n 3D-33: electron as PARTICLE — crossing the CRITICAL LINE (winding theorem):")
    println("   The hypothesis under test (user, 2026-09-02): a moving electron, measured")
    println("   as a particle, ALWAYS crosses the critical line — the line where the zeros")
    println("   live. AB dictionary (the suite's Hilbert–Pólya picture): the vortex LINE")
    println("   is the puncture, its polar-gauge branch-cut ray is the critical line (the")
    println("   analog of Re s = 1/2), and one orbit = 2π of accumulated phase = TWO")
    println("   zero slots of the θ/π counting (each ζ zero advances θ by π). Topology")
    println("   of the punctured plane: a trajectory winding around the line crosses the")
    println("   ray once per COMPLETED revolution (net = sign·floor(|Δθ|/2π), +1 boundary")
    println("   branch) — measured below for e⁻ and e⁺; non-winding arcs never leave the")
    println("   same branch (|net| ≤ 1).")
    σ = 0.4; qv = 0.3; vz0 = 0.25; B0 = 1.0
    # Launch OFF the branch-cut ray (θ₀ = 0.297 rad) — starting exactly ON the
    # ray would make the first crossing degenerate (no y-sign flip to detect).
    # Trap geometry: exact cyclotron circles ρ = v⊥/(|q|B0) = 1 inside r ≤ 3.5.
    # WINDING ⇔ the guiding center sits at |d_gc| < ρ from the line: for the
    # launch (1.162, 0.35) this is e⁻ with vy>0 and e⁺ with vy<0 (center at
    # (0.162, 0.35), |d| = 0.38 < 1 → the circle ENCLOSES the line); the
    # opposite launches give circles around (2.16, 0.35) — no winding.
    x0 = sqrt(1.2^2 - 0.35^2); y0 = 0.35; vperp = 1.0
    T = 30.0 # ~4.8 revolutions (T_cyc = 2π)
    cases = (
        ("e⁻ WINDING",   -1.0, +vperp, true),
        ("e⁺ WINDING",   +1.0, -vperp, true),
        ("e⁻ no-wind",   -1.0, -vperp, true),  # same trap, opposite launch
        ("e⁺ no-wind",   +1.0, +vperp, true),
        ("e⁻ free tube", -1.0, +vperp, false), # Gaussian-tube scattering (E7-like)
        ("e⁺ free tube", +1.0, -vperp, false),
    )
    all_ok = true
    paths = Dict{String, NamedTuple}()
    θ0 = atan(y0, x0)
    for (k, (label, sgn, vperp_s, trapped)) in enumerate(cases)
        prog_update(k / length(cases), "integrate $label") # FIX 2026-09-02d: never silent
        r = _d3_helix_shoot(sgn, x0, y0, 0.0, vperp_s, vz0, qv, σ;
                            T = T, dt = 0.005, trap = trapped, B0 = B0)
        θ = r.theta
        # Topology for OPEN trajectories (exact): a monotone-winding arc makes
        # one ray crossing per COMPLETED revolution — net = sign·floor(|Δθ|/2π)
        # — plus one extra crossing iff it ends on the far side of the ray
        # from its start (the ceil branch). Non-winding arcs return to the
        # same branch: |net| ≤ 1 (parity).
        W = round(Int, θ / (2π))            # signed revolutions of the arc
        nrev = abs(θ - θ0) / (2π)           # revolutions swept (θ0 ≈ 0.047 rev)
        net = r.nplus - r.nminus
        fl, ce = floor(Int, nrev), ceil(Int, nrev)
        ok_case = if abs(W) ≥ 4 # winding rows
            (net == sign(W) * fl || net == sign(W) * ce) && abs(net) ≥ 3
        else
            abs(net) ≤ 1
        end
        all_ok &= ok_case
        @printf("   %-14s θ/2π = %+7.2f rev | N₊ = %2d N₋ = %2d | net = %+2d (floor|Δθ|/2π = %2d) | zero slots θ/π = %6.1f → %s\n",
                label, θ / (2π), r.nplus, r.nminus, net, fl, abs(θ) / π, ok_case ? "OK" : "FAIL")
        paths[label] = r
    end
    # the zero-slot staircase: successive crossings climb the line (vz > 0)
    rw = paths["e⁻ WINDING"]
    if length(rw.cross_z) ≥ 2
        asc = all(diff(rw.cross_z) .> 0)
        @printf("   staircase: %d crossings climb the line (Δz per orbit ≈ %.3f, ascending: %s)\n",
                length(rw.cross_z), mean(diff(rw.cross_z)), asc ? "YES" : "no")
        p2 = RepPlot("3D-33: the zero-slot staircase — crossing height along the critical line",
                     "crossing #", "z")
        add_series!(p2, "z at crossings", collect(1.0:length(rw.cross_z)), rw.cross_z, 's')
        rep_plot!(p2)
    end
    p1 = RepPlot("3D-33: winding e⁻ orbits around the flux line + the critical ray (x>0, y=0)",
                 "x", "y")
    add_series!(p1, "e⁻ trap orbit", [s[1] for s in rw.path], [s[2] for s in rw.path], 'l')
    nwx = paths["e⁻ free tube"]
    add_series!(p1, "free-tube control", [s[1] for s in nwx.path], [s[2] for s in nwx.path], 'l')
    add_series!(p1, "critical ray", [0.0, 3.6], [0.0, 0.0], 'l')
    rep_plot!(p1)
    # AB phase per revolution: the orbit ENCLOSES the line → Δφ = 2π·(q mod 1)
    dphi = 2π * (qv - floor(qv))
    @printf("   AB phase per winding orbit: Δφ = 2π·(q mod 1) = %.4f rad (q = %.1f) —\n", dphi, qv)
    println("   the wave counterpart of the same orbit (E7/E8: levels Eₙ ∝ (n−q)²).")
    rep_note!("THE CRITICAL-LINE CROSSING THEOREM: on the punctured plane (the vortex " *
              "line removed) a trajectory winding around the puncture crosses any ray " *
              "from it once per COMPLETED revolution (net = sign·floor(|Δθ|/2π), +1 " *
              "boundary branch when it ends across the ray) — measured exactly for " *
              "both charges; non-winding arcs return to the same branch (|net| ≤ 1). " *
              "A winding electron therefore ALWAYS crosses the branch-cut ray — the AB " *
              "critical line — and the crossings climb the line one zero-slot after " *
              "another (vz>0 staircase). The user's hypothesis holds in this precise " *
              "topological form. HILBERT–PÓLYA DICTIONARY (interpretation, stated as " *
              "a dictionary): orbit phase θ ↔ zeta ordinate via the zero-counting " *
              "θ(tₖ) = πk; one revolution (2π) = two zero slots; the ray = Re s = 1/2. " *
              "The topology is a theorem; the identification with the Riemann line is " *
              "the hypothesis this suite is built to explore.")
    @printf("   verdict: %s\n", all_ok ? "crossing topology OK (one crossing per revolution, both charges)" : "FAIL")
    return all_ok
end

# ── 3D-34: wave mode — the ζ critical strip ────────────────────────────────
function t3_34(cfg)
    println("\n 3D-34: electron as WAVE — the ζ landscape on the critical strip:")
    println("   The wave-mode electron is NOT a point: it is smeared over the orbit and")
    println("   'performs' the WHOLE function (user hypothesis). The suite's honest wave")
    println("   object is ζ(s) itself: the famous 2D graph ζ(1/2+it), every zero lying")
    println("   ON the critical line Re s = 1/2 (Hilbert–Pólya: those zeros ARE the")
    println("   e⁻/e⁺ levels of the conjectural operator). This test BUILDS ζ from")
    println("   scratch (Euler–Maclaurin — the standard modern evaluator) and VERIFIES")
    println("   the zero-line claim against the embedded Odlyzko zeros.")
    # A. evaluator anchors (exact closed forms)
    z2 = _d3_zeta(complex(2.0)); e2 = abs(z2 - π^2 / 6) / (π^2 / 6)
    z4 = _d3_zeta(complex(4.0)); e4 = abs(z4 - π^4 / 90) / (π^4 / 90)
    zh = _d3_zeta(complex(0.5, 0.0)); eh = abs(zh + 1.4603545088095868)
    @printf("   anchors: ζ(2) rel.err %.2e (π²/6) | ζ(4) rel.err %.2e (π⁴/90)\n", e2, e4)
    @printf("            ζ(1/2) = %.13f (abs.err %.2e vs −1.4603545088095868)\n", zh, eh)
    # B. zero bracketing on the critical line — the first 10 embedded zeros
    zs10 = (14.134725142, 21.022039639, 25.010857580, 30.424876126,
            32.935061588, 37.586178159, 40.918719012, 43.327073281,
            48.005150881, 49.773832478)
    δ = 0.02
    bracketed = 0; worst = 0.0
    for g in zs10
        Zl = _d3_hardy_Z(g - δ); Zr = _d3_hardy_Z(g + δ)
        Zl * Zr < 0 && (bracketed += 1)
        a, b = g - δ, g + δ # bisect to the sign-change root
        Za = Zl
        for _ in 1:40
            mid = (a + b) / 2
            Zm = _d3_hardy_Z(mid)
            if Za * Zm <= 0; b = mid; else; a = mid; Za = Zm; end
        end
        worst = max(worst, abs((a + b) / 2 - g))
    end
    @printf("   critical line: %d/10 sign changes straddle the embedded γₖ; worst |root−γₖ| = %.1e\n",
            bracketed, worst)
    println("   → the zeros of the WAVE function sit exactly where the dataset says: ON")
    println("   Re s = 1/2 (the line the particle-mode electron crosses in 3D-33).")
    # C. the famous 2D graph
    tgrid = collect(0.0:0.025:60.0)
    Zv = [_d3_hardy_Z(t) for t in tgrid]
    p1 = RepPlot("3D-34: Hardy Z(t) = e^{iθ}ζ(1/2+it) — the wave-mode landscape", "t", "Z(t)")
    add_series!(p1, "Z(t)", tgrid, Zv, 'l')
    add_series!(p1, "zero line", [0.0, 60.0], [0.0, 0.0], 'l')
    add_series!(p1, "embedded γₖ", collect(zs10), zeros(length(zs10)), 's')
    rep_plot!(p1)
    # D. the critical-strip heatmap |ζ(σ+it)| (rows σ, cols t; row 1 = bottom)
    if REP.enabled && !isempty(REP.run_dir)
        prog_update(0.5, "strip heatmap — ζ over σ×t grid") # FIX 2026-09-02d
        sigmas = collect(0.0:0.025:1.0)
        tvals = collect(0.05:0.1:40.0) # t>0: never hits the s=1 pole
        M = [log10(1.0 + abs(_d3_zeta(complex(σ, t)))) for σ in sigmas, t in tvals]
        slugbase = joinpath(REP.run_dir, "test_234_zeta_strip", "plots")
        mkpath(slugbase)
        write_heatmap_png(joinpath(slugbase, "zeta_critical_strip.png"), M)
        write_heatmap_svg(joinpath(slugbase, "zeta_critical_strip.svg"), M,
            "ζ(σ+it): |ζ| (log) — the zeros pile up on σ = 1/2", "t", "σ (critical strip)")
        println("   strip heatmap (|ζ(σ+it)|, σ∈[0,1], t∈[0,40]) → ", slugbase)
    else
        println("   (reporting off — strip heatmap skipped)")
    end
    # E. wave/particle complementarity (the user's picture, precisely stated)
    println("\n   COMPLEMENTARITY (the two new modes, one line each):")
    println("   • WAVE: |ψ|² smeared over the orbit — the electron IS the whole function;")
    println("     the AB twist makes the orbital wave single-valued ⇒ n − q ∈ ℤ ⇒ orbit")
    println("     levels Eₙ ∝ (n−q)² (E8) — the Hilbert–Pólya spectral dictionary.")
    println("   • PARTICLE (3D-33): every winding orbit crosses the critical ray once per")
    println("     revolution — the crossings climb the zero slots θ/π = 2, 4, 6, …")
    rep_note!("WAVE MODE: ζ(s) is evaluated for complex s by the Euler–Maclaurin tail " *
              "expansion (self-anchored on ζ(2) = π²/6, ζ(4) = π⁴/90, ζ(1/2) = " *
              "−1.4603545088… and the first ten Odlyzko zeros: Z(γₖ±δ) straddles 0 and " *
              "bisection lands within tolerance of each γₖ). The 2D graph is the same " *
              "construction the user references ('the zeta function graph on the " *
              "internet'): oscillating Z(t) with every zero ON the t-axis — i.e. ON the " *
              "critical line. In the user's hypothesis the wave-mode electron smeared " *
              "over the atomic orbit performs exactly this function, while the " *
              "particle-mode measurement (3D-33) sits on a branch and always crosses " *
              "the line of zeros. The suite's contribution: the orbit levels (n−q)² " *
              "(E8) are the SAME dictionary — fractional AB charge q shifts the " *
              "quantization exactly like the zeros shift the Gram points.")
    okA = e2 < 1e-12 && e4 < 1e-12 && eh < 1e-10
    okB = bracketed == 10 && worst < 5e-3
    @printf("   verdict: anchors %s | zero-line %s\n", okA ? "OK" : "FAIL", okB ? "OK" : "FAIL")
    return okA && okB
end

