"""3D Lab menu (main-menu key 'd3' — the bare digit '3' is
test 3 again). Independent of tests 1-38 / run-all. 's' opens the extended
D3 parameter menu (matrix size, α, tz, W, mass, boundary, vortex lines, seed).
3D-31…3D-34 (v20.0) are the modern Dirac e⁻/e⁺ block: zitterbewegung,
charge conjugation, the particle-mode critical-line crossing theorem, and
the wave-mode ζ critical-strip landscape."""
function three_d_menu!(cfg::Config)
    _register_3d!()
    reads3 = 0
    while true
        println("\n════════════════ 3D LAB — Hofstadter stack with vortex lines ════════════════")
        println("  (independent implementation — NOT included in 'run all tests' 1-38)")
        @printf("  D3 defaults: L=%d (%d³=%d sites) | α=%g | tz=%g | W=%g | mass=%g | %s | lines=%d×q=%g | seed=%d\n",
                cfg.d3_L, cfg.d3_L, cfg.d3_L^3, cfg.d3_alpha, cfg.d3_tz, cfg.d3_W,
                cfg.d3_mass, cfg.d3_boundary, cfg.d3_nv_lines, cfg.d3_line_q, cfg.d3_seed)
        for t in T3D
            @printf("  3D-%-2d. %s — %s\n", t.id, t.title, t.about)
        end
        println("  a.  Run ALL 3D tests")
        println("  s.  3D parameter settings — L, α, tz, W, mass, boundary, vortex lines, …")
        println("  v.  View current 3D parameters")
        println("  r.  Reset 3D parameters to launch defaults (10×10×10)")
        println("  q.  Return")
        print(" > ")
        ans = strip(readline())
        isempty(ans) && (reads3 += 1; reads3 >= 50 && return; continue)
        reads3 = 0
        try
            if ans == "q" || ans == "й"
                return
            elseif ans == "s" || ans == "ы" # extended parameter menu
                d3_params_menu!(cfg)
                continue
            elseif ans == "v" || ans == "м" # quick view
                _d3_params_show(cfg)
                continue
            elseif ans == "r" || ans == "к" # reset
                _d3_params_reset!(cfg)
                continue
            elseif ans == "a" || ans == "ф"
                npass = 0
                for t in T3D
                    rep_begin!(200 + t.id, "3D[$(t.id)] $(t.title)")
                    # FIX 2026-09-02d: the 3D menu now owns a progress bar —
                    # a long dense-eig sweep is never silent (TTY: live bar;
                    # piped: sparse milestone lines with timestamps).
                    owned = _prog_owned_start("3D-$(t.id)")
                    t0 = time()
                    res = rep_tee_stdout() do
 # echo the effective 3D parameter block (also lands in the report log)
                        @printf("D3 PARAMETERS: L=%d α=%g tz=%g W=%g mass=%g stagger=%s boundary=:%s lines=%d q=%g neutrals=%s seed=%d\n",
                                cfg.d3_L, cfg.d3_alpha, cfg.d3_tz, cfg.d3_W, cfg.d3_mass,
                                cfg.d3_tz_stagger, cfg.d3_boundary, cfg.d3_nv_lines,
                                cfg.d3_line_q, cfg.d3_neutrals, cfg.d3_seed)
                        t.runner(cfg)
                    end
                    owned && prog_finish(res === true, time() - t0)
                    rt = REP.current
 # (rep_auto_plots! retired 2026-08-31 — a 3D test without an
                    # explicit RepPlot now reports "no series plots" instead
                    # of a scraped-junk curve)
                    if rt !== nothing
                        rep_finish!(200 + t.id, res === true ? "PASS" : "DONE",
                            last_log_line())
                    end
                    res === true && (npass += 1)
                end
                @printf("\n 3D suite: %d/%d explicit PASS\n", npass, length(T3D))
                # FINAL_REPORT inside the 3D section too (user spec 2026-08-29)
                rep_finalize_run("3D Lab — Hofstadter stack suite (all tests)")
            else
                # FIX 2026-09-02d: tolerate «31», «3d31», «3D-31» spellings
                tnum = ans
                low = lowercase(tnum)
                if startswith(low, "3d")
                    tnum = lstrip(tnum[3:end], ['-'])
                end
                n = tryparse(Int, tnum)
                n === nothing && (println("  No such test — enter 1-$(length(T3D)) (e.g. 31 or 3d-31)."); continue)
                t = findfirst(x -> x.id == n, T3D)
                t === nothing && (println("  No such test (1-$(length(T3D)))."); continue)
                tt = T3D[t]
                println("\n─── 3D-$(tt.id): $(tt.title) — $(tt.about) ───")
 # the prompt now exposes the parameter menu before the run
                print("  Run: [Enter]=current 3D settings / s=change parameters / q=cancel ")
                ok = strip(readline())
                ok == "q" && continue
                ok in ("s", "ы") && d3_params_menu!(cfg)
                rep_begin!(200 + tt.id, "3D[$(tt.id)] $(tt.title)")
                owned = _prog_owned_start("3D-$(tt.id)") # FIX 2026-09-02d: live bar
                t0 = time()
                res = rep_tee_stdout() do
                    @printf("D3 PARAMETERS: L=%d α=%g tz=%g W=%g mass=%g stagger=%s boundary=:%s lines=%d q=%g neutrals=%s seed=%d\n",
                            cfg.d3_L, cfg.d3_alpha, cfg.d3_tz, cfg.d3_W, cfg.d3_mass,
                            cfg.d3_tz_stagger, cfg.d3_boundary, cfg.d3_nv_lines,
                            cfg.d3_line_q, cfg.d3_neutrals, cfg.d3_seed)
                    tt.runner(cfg)
                end
                owned && prog_finish(res === true, time() - t0)
                rt = REP.current
 # (rep_auto_plots! retired 2026-08-31 — see the run-all branch)
                if rt !== nothing
                    rep_finish!(200 + tt.id, res === true ? "PASS" : "DONE",
                        last_log_line())
                end
                rep_finalize_run("3D Lab — single test 3D-$(tt.id)")
            end
        catch err
            err isa InterruptException && (println("\n^C — interrupted."); continue)
            println("  ERROR: ", sprint(showerror, err))
        end
    end
end


# ── 20. QUICK CHECK (16×16 → 32×32 two-pass) ───────────────────────────
function quick_check_all(zeta_zeros::Vector{Float64}, cfg::Config)
    println("\n QUICK CHECK: the full 38-test suite on 16×16 (pass 1) and 32×32 (pass 2)")
    watched = (:ab_nx, :ab_ny, :ab_nx_secondary, :ab_ny_secondary, :ab_run_two_pass,
               :ab_run_third_pass, :ab_nv_list, :ab_nv_list_secondary,
               :ab_n_realizations, :ab_ks_bootstrap_n)
    saved = [(f, getfield(cfg, f)) for f in watched]
    try
        cfg.ab_nx = 16; cfg.ab_ny = 16
        cfg.ab_nx_secondary = 32; cfg.ab_ny_secondary = 32
        cfg.ab_run_two_pass = true
        cfg.ab_run_third_pass = false # QUICK CHECK stays fast — no 19c/29c/31c series
        cfg.ab_nv_list = [2]; cfg.ab_nv_list_secondary = [2]
        cfg.ab_n_realizations = 2
        cfg.ab_ks_bootstrap_n = min(cfg.ab_ks_bootstrap_n, 50)
        run_all_tests(zeta_zeros, cfg)
    finally
        for (f, v) in saved
            setproperty!(cfg, f, v)
        end
    end
    println(" QUICK CHECK done — config restored to previous values.")
    rep_finalize_run("QUICK CHECK — 16×16 / 32×32 two-pass suite")
    return
end

