 julia ab_cloud_v20.jl --L-max 140 --L-count 8 --test 14
 julia ab_cloud_v20.jl --config --lang ru
 """)
 exit(0)
 else
 # FIX 2026-08-31: unknown flags were skipped SILENTLY — a typo like
 # `--ab-w 4` (the flag is --ab-W) or a missing value then silently
 # changed nothing. Print an honest warning and keep going.
 @printf(" WARNING: unrecognized CLI argument \"%s\" (flag typo or missing value?)\n", a)
 i += 1
 end
 end

 # Resolve a pending --L-max (and optional --L-count) into a geometric grid.
 # This is done AFTER the loop so the two flags can appear in either order.
 if pending_l_max !== nothing
 n_pts = pending_l_count === nothing ? 8 : pending_l_count
 cfg.rigidity_L_values = geometric_l_grid(pending_l_max, n_pts)
 end
end

function main()
 cfg = default_config()
 parse_args!(cfg)
 rep_init!(cfg)

 if cfg.lang == "en" && haskey(ENV, "LANG") && startswith(ENV["LANG"], "ru")
 cfg.lang = "ru"
 end

 println(repeat("=", 60))
 println(fmt(cfg, "title"))
 println("Author: Isaev Iskhak Khamzatovich | ORCID: 0009-0003-7299-0701")
 println("Repo: https://github.com/wild8highlander/research-papers")
 println("Plots.jl: $(PLOTS_AVAILABLE ? "available" : "not available (ASCII fallback)")")
 println("Self-contained: 50,000 embedded Riemann zeros (Odlyzko)")
 println("Default: requesting $(cfg.zeros_count) zeros from source '$(cfg.source)'")
 println(repeat("=", 60))

 if cfg.test == "config_then_interactive"
 config_menu!(cfg)
 cfg.test = "interactive"
 end

 zeta_zeros = load_zeros(cfg)
 if isempty(zeta_zeros)
 println(msg(cfg, "no_data"))
 println("\nPress 'c' to configure data directory, or any other key to exit.")
 answer = strip(readline())
 if answer == "c" || answer == "с"
 config_menu!(cfg)
 zeta_zeros = load_zeros(cfg)
 if isempty(zeta_zeros)
 println(msg(cfg, "no_data"))
 # FIX 2026-09-02: exit(1) here killed an INTERACTIVE session that
 # had include()d this file (the footer runs main() when
 # isinteractive()). Script mode still exits with code 1; a REPL
 # session just returns control to the caller instead of dying.
 isinteractive() || exit(1)
 return
 end
 else
 isinteractive() || exit(1)
 return
 end
 end

 if cfg.test == "all"
 run_all_tests(zeta_zeros, cfg)
 rep_finalize_run("AB-Cloud v20 — full 38-test verification suite")
 elseif cfg.test != "interactive"
 # FIX 2026-09-02: --test abc (or --test 99) used to die with a raw
 # ArgumentError stack trace from parse(Int, ...) — or to run a
 # nonexistent id silently returning false. Validate cleanly first.
 test_id = tryparse(Int, cfg.test)
 if test_id === nothing || !(test_id in SUITE_IDS)
 println(" ERROR: --test expects 'all' or an integer in 1-38, got '$(cfg.test)'")
 isinteractive() || exit(1)
 return
 end
 # Single-test run also uses two-pass wrapper when enabled
 if cfg.ab_run_two_pass && !cfg.ab_run_primary_only
 run_test_two_pass(test_id, zeta_zeros, cfg)
 else
 run_test(test_id, zeta_zeros, cfg)
 end
 rep_finalize_run("AB-Cloud v20 — single-test run (test $(test_id))")
 else
 # when stdin is exhausted/closed (piped driver, /dev/null, IDE
 # runner) readline() returns "" forever — the menu was redrawn in an
 # infinite loop. 50 consecutive empty reads → graceful exit.
 # any exception inside the loop (a typo like "10k" in the 'r'
 # branch → parse(Int,"10k") ArgumentError, or a failed test) used to kill
 # the whole program; now it is reported and the menu redraws.
 empty_reads = 0
 while true
 try
 show_menu(cfg)
 print(msg(cfg, "prompt"))
 answer = strip(readline())

 if isempty(answer)
 empty_reads += 1
 empty_reads >= 50 && (println("\nNo input on stdin (EOF) — exiting menu."); break)
 continue
 end
 empty_reads = 0

 if answer == "q" || answer == "й"
 println(cfg.lang == "ru" ? "До свидания!" : "Goodbye!")
 rep_finalize_run("AB-Cloud v20 — interactive session")
 break
 elseif answer == "a" || answer == "ф"
 run_all_tests(zeta_zeros, cfg)
 # FINAL_REPORT right after the suite — no need to wait for 'q'
 rep_finalize_run("AB-Cloud v20 — full 38-test verification suite")
 elseif answer == "p" || answer == "з"
 list_presets()
 print("Enter preset name [Enter=cancel]: ")
 pname = strip(readline())
 if !isempty(pname)
 if apply_preset!(cfg, pname)
 println("Preset '$pname' applied. Use 'c' to review or 'a' to run all tests.")
 end
 end
 elseif answer == "l" || answer == "д"
 physics_lab_menu!(cfg)
 elseif answer == "f" || answer == "а"
 quick_check_all(zeta_zeros, cfg)
 elseif lowercase(answer) in ("d3", "dз") # 'd3' (latin) — bare '3' runs TEST 3 again
 three_d_menu!(cfg)
 elseif answer == "3"
 println("  The 3D lab moved to key 'd3' — typing 3 now runs TEST 3.")
 run_test(3, zeta_zeros, cfg)
 elseif answer == "c" || answer == "с"
 config_menu!(cfg)
 elseif answer == "r" || answer == "к"
 println(cfg.lang == "ru" ?
 "\nТекущие настройки: zeros=$(cfg.zeros_count), source=$(cfg.source), data_dir=$(cfg.data_dir)" :
 "\nCurrent: zeros=$(cfg.zeros_count), source=$(cfg.source), data_dir=$(cfg.data_dir)")
 print(cfg.lang == "ru" ? "Новое кол-во нулей [Enter=keep]: " : "New zeros count [Enter=keep]: ")
 v = strip(readline())
 !isempty(v) && (cfg.zeros_count = parse(Int, v))
 print(cfg.lang == "ru" ? "Новый источник [Enter=keep]: " : "New source [Enter=keep]: ")
 v = strip(readline())
 !isempty(v) && (cfg.source = v)
 # Invalidate GUE ref cache if matrix params changed (handled in get_gue_ref)
 zeta_zeros_new = load_zeros(cfg)
 if !isempty(zeta_zeros_new)
 zeta_zeros = zeta_zeros_new
 println(cfg.lang == "ru" ? "Нули перезагружены: $(length(zeta_zeros))" : "Zeros reloaded: $(length(zeta_zeros))")
 else
 println(msg(cfg, "no_data"))
 end
 elseif !isempty(answer)
 # tryparse — NOT try/catch around run_test: the old catch ALSO swallowed
 # real test crashes (Test 29's torus-flux assert surfaced as a misleading
 # "Invalid input" instead of the actual error). Parse failures print the
 # hint; genuine test exceptions reach the outer catch below, which prints
 # the full error text and returns to the menu.
 test_id = tryparse(Int, answer)
 if test_id === nothing
 println("Invalid input. Enter 1-38, 'a', 'p', 'c', 'l', 'd3', 'f', 'r', or 'q'.")
 elseif test_id in SUITE_IDS
 run_test(test_id, zeta_zeros, cfg)
 else
 println("Invalid test number. Use 1-38.")
 end
 end
 catch e
 # stay alive — report and redraw the menu.
 if e isa InterruptException
 println("\n^C — interrupted, back to menu (type q to quit).")
 else
 println("\nERROR: ", sprint(showerror, e))
 println("Back to menu (type q to quit).")
 end
 end
 end
 end
end

# run main() when executed as a
# script AND when include()d into an INTERACTIVE session (REPL / IDE
# "execute file"). A bare trailing `main()` would open the interactive
# menu right after include(); non-interactive include() stays a
# silent library load
# but SILENTLY skipped main() on include() — users perceived this as
# "the interactive menu does not open". New behavior:
#   julia ab_cloud_v20.jl        → menu (script mode)
#   include("ab_cloud_v20.jl")   → menu when the session is interactive;
#                                  silent library mode otherwise (probe
#                                  drivers, --test automation, notebooks)
if (abspath(PROGRAM_FILE) == @__FILE__) || isinteractive()
    main()
end
